"use strict";
const TOPICS = {
  1:{name:"Tema 1",desc:"Terapéutica veterinaria"},
  2:{name:"Tema 2",desc:"Autacoides (histamina, serotonina, péptidos, eicosanoides y NO)"},
  3:{name:"Tema 3",desc:"AINEs, antiartríticos y antirreumatoideos"},
  4:{name:"Tema 4",desc:"Antiinflamatorios esteroideos"},
  5:{name:"Tema 5",desc:"Terapéutica cardiovascular"}
};

/* t = tema, q = pregunta, o = opciones (orden original A-D), a = índice correcto,
   m = índice marcado en los apuntes cuando NO coincide con la correcta, d = pregunta dudosa, n = apuntes */
const QUESTIONS = [
{t:5,q:"¿Cuál de los siguientes fármacos NO está indicado en la cardiomiopatía hipertrófica?",o:["Verapamilo","Atenolol","Dobutamina","Enalapril"],a:2,
n:"En la cardiomiopatía hipertrófica el problema es diastólico: el ventrículo está engrosado, rígido e hipercontráctil. Se usan fármacos que relajan y enlentecen el corazón: β-bloqueantes (atenolol), antagonistas del Ca²⁺ (diltiazem, verapamilo) y, si hay ICC, IECAs (enalapril). Los inotropos positivos como la <b>dobutamina están contraindicados</b>: aumentan la contractilidad y empeoran la obstrucción del tracto de salida."},
{t:5,q:"Respecto a los antiarrítmicos de clase I. Señalar la correcta:",o:["Aumentan la velocidad de despolarización y de expansión del estímulo en el miocardio","Acortan el periodo refractario","Solo utilizados en alteraciones intensas del ritmo que alteran el gasto cardiaco","Bloquean el canal independientemente de su estado"],a:2,
n:"Clase I = bloqueantes de canales de Na⁺. <b>Disminuyen</b> la velocidad de despolarización (fase 0) y de conducción y, en general, <b>prolongan</b> el periodo refractario. El bloqueo es <b>dependiente del estado</b> del canal (se unen al canal abierto/inactivado). Por su efecto proarritmogénico se reservan para alteraciones intensas del ritmo que comprometen el gasto cardiaco."},
{t:5,q:"Fármacos inotrópicos. Señala la proposición correcta:",o:["La dopamina es agonista adrenérgico β1, β2 y α1 con más acción inotrópica que vasoconstrictora","Prenalterol es agonista adrenérgico α1 útil en hipertensión portal","Amrinona posee más acción vasodilatadora que inotrópica positiva","Dobutamina es agonista de receptores dopaminérgicos D1 y D2"],a:2,
n:"Amrinona y milrinona (inhibidores de PDE3) son «inodilatadores» con <b>mayor efecto vasodilatador que inotrópico</b>.<br>• Dopamina: agonista D1, β1 y α1 (no β2).<br>• Prenalterol: agonista <b>parcial β1</b>.<br>• Dobutamina: agonista β1 (algo β2 y α1); no actúa sobre receptores dopaminérgicos."},
{t:5,q:"Bloqueantes de los canales lentos de Ca²⁺. Señala la proposición FALSA:",o:["Útiles en estenosis aórtica e hipertensión arterial","Contraindicados en intoxicación digitálica","Poseen actividad depresora intensa de la conducción AV y en células de Purkinje","De elección en taquicardias ventriculares"],a:3,
n:"Los antagonistas del Ca²⁺ (verapamilo, diltiazem) deprimen la conducción AV: son de elección en taquicardias <b>supraventriculares</b>, no ventriculares. Están contraindicados en la intoxicación digitálica (el verapamilo aumenta los niveles de digoxina y suma depresión AV)."},
{t:5,q:"IECAs. Señalar la proposición incorrecta:",o:["Aumentan el flujo renal sin apenas cambios en la filtración glomerular","Producen efecto cronotropo positivo leve por activación simpática","Asociados con AINEs pueden producir hiperpotasemia","Disminuyen la resistencia vascular periférica y retrasan el desarrollo de aterosclerosis"],a:1,
n:"Los IECA producen vasodilatación <b>sin taquicardia refleja</b>: al reducir la angiotensina II disminuyen el tono simpático. Aumentan el flujo renal con poco cambio en la FG, pueden dar hiperpotasemia (más con AINEs o diuréticos ahorradores de K⁺), reducen la RVP y frenan la remodelación vascular y la aterosclerosis.<br>En otra versión de esta pregunta, en lugar del efecto cronotropo aparece «Están contraindicados en hipertensión», que también es falsa: los IECA son antihipertensivos de primera línea."},
{t:5,q:"Otros vasodilatadores. Señalar la proposición incorrecta:",o:["Prazosina, bloqueante α1, es útil en ICC de origen valvular","Isoxsuprina es un arteriodilatador útil en laminitis","El inhibidor de la renina, aliskiren, es útil en hipertrofia cardiaca","Sildenafilo, inhibidor de PDE5, es útil para reducir la hipertensión aórtica"],a:3,
n:"El sildenafilo (inhibidor de PDE5) se usa en <b>hipertensión pulmonar</b> (en perros), no aórtica.<br>• Prazosina: bloqueante α1, vasodilatador mixto útil en ICC valvular.<br>• Isoxsuprina: vasodilatador usado en laminitis y enfermedad navicular en caballos.<br>• Aliskiren: inhibidor directo de la renina."},
{t:5,q:"Digitálicos. Señalar la proposición correcta:",o:["Se acumulan en tejido adiposo","La digoxina se elimina principalmente vía hepática en forma de metabolitos","En perro la digoxina posee una vida media más prolongada que la digitoxina","La hiperpotasemia disminuye su actividad inotrópica"],a:2,d:true,
n:"En el <b>perro</b> la digoxina tiene vida media más larga (≈20–55 h) que la digitoxina (≈8–12 h); en humanos ocurre al revés.<br>• Se acumulan en corazón, riñón, hígado y músculo, pero <b>muy poco en tejido adiposo</b> (se dosifica por peso magro).<br>• La digoxina se elimina sobre todo por <b>vía renal sin metabolizar</b>.<br>• Potasio: la <b>hipopotasemia aumenta su toxicidad</b>. La D tiene parte de verdad (el K⁺ alto compite con la digoxina en la Na⁺/K⁺-ATPasa), pero la respuesta esperada es la C."},
{t:2,q:"¿Cuál NO es un efecto de la histamina?",o:["Disminución de la resistencia periférica e hipotensión","Constricción de venas hepáticas en el perro","Efecto cronotropo e inotropo negativo","Relajación de rumen y retículo"],a:2,
n:"En el corazón la histamina tiene efecto <b>cronotropo e inotropo POSITIVO</b> (receptores H2) y enlentece la conducción AV (H1). Otros efectos: vasodilatación de vasos pequeños → ↓RVP e hipotensión; en el perro constricción de las venas hepáticas (secuestro de sangre esplácnica en la anafilaxia)."},
{t:5,q:"Los nitratos orgánicos (dilatadores coronarios). Señalar la incorrecta:",o:["Buena disponibilidad oral pero duración de acción inferior a gliceril trinitrato","Son vasodilatadores mixtos con mayor actividad sobre venas","Disminuyen la demanda de oxígeno","Mejoran la perfusión subendocárdica al evitar estenosis espasmódicas de coronarias"],a:0,
n:"Los nitratos orales (dinitrato y mononitrato de isosorbida) tienen buena biodisponibilidad oral y una duración de acción <b>MAYOR</b> que la nitroglicerina (gliceril trinitrato), que es de acción muy corta. Son vasodilatadores mixtos de predominio venoso (↓precarga), disminuyen la demanda de O₂ y mejoran la perfusión subendocárdica."},
{t:2,q:"Antihistamínicos H1 (2ª generación). Señala la incorrecta:",o:["Presentan vidas medias prolongadas que permiten su administración una vez al día","Su excreción es principalmente por vía hepática","Muchos de ellos poseen metabolitos activos que contribuyen a su acción terapéutica","Acción más selectiva presentando poco bloqueo de otros receptores autonómicos"],a:1,
n:"AntiH1 de 2ª generación (loratadina, cetirizina, fexofenadina…): vida media larga (una dosis al día), metabolitos activos, más selectivos (poco bloqueo colinérgico/adrenérgico), poco paso de la BHE (menos sedación) y alta unión a proteínas. Según el temario su <b>excreción es fundamentalmente RENAL</b>."},
{t:2,q:"Efectos de los antihistamínicos H2. Señala la proposición incorrecta:",o:["Ranitidina estimula la secreción de prolactina","Nizatidina no se biotransforma y es útil en casos de insuficiencia hepática","Presentan buena absorción oral aunque con efecto de primer paso","No presentan efectos a nivel central"],a:0,d:true,
n:"El antiH2 que estimula la prolactina y tiene efecto antiandrogénico es la <b>CIMETIDINA</b> (que además inhibe el citocromo P450). La ranitidina prácticamente no modifica la prolactina a dosis normales.<br>• Nizatidina: apenas se biotransforma (eliminación renal) → útil en insuficiencia hepática.<br>• Buena absorción oral con efecto de primer paso.<br>• Pasan poco la BHE (aunque la cimetidina puede dar confusión en pacientes mayores)."},
{t:2,q:"Efectos sobre la serotonina. Señale la respuesta incorrecta:",o:["Los inhibidores de su recaptación son serotoninérgicos indirectos utilizados como antidepresivos","Los agonistas 5-HT4 son potentes antieméticos","Los antagonistas 5-HT2 provocan estimulación de fibra muscular lisa vascular y uterina","Los setrones no son útiles en vómitos por cinetosis"],a:1,d:true,
n:"Las claves de clase marcan esta: los <b>agonistas 5-HT4</b> (cisaprida, mosaprida) son sobre todo <b>procinéticos</b>, no antieméticos potentes; los antieméticos potentes son los <b>antagonistas 5-HT3</b> (setrones), que no sirven para la cinetosis.<br>Ojo: tal como está escrita, la opción de los antagonistas 5-HT2 tampoco es cierta: los receptores 5-HT2 median la <b>contracción</b> del músculo liso vascular, uterino y bronquial, y sus antagonistas (ketanserina) la bloquean. Si en tu examen dice «agonistas 5-HT2», esa sí sería cierta."},
{t:2,q:"La angiotensina II… Señalar la proposición incorrecta:",o:["Por unión con el receptor AT2 provoca vasoconstricción y activación simpática","Por unión con el receptor AT2 tiene actividad antiproliferativa y vasodilatadora","La interacción con el receptor AT1 promueve la hipertrofia y proliferación de miocitos","Por interacción con el receptor AT1 se estimula la fibrosis cardiaca y la formación de superóxidos"],a:0,m:1,
n:"<b>AT1</b>: vasoconstricción, activación simpática, liberación de aldosterona y ADH, hipertrofia y proliferación, fibrosis y formación de superóxidos.<br><b>AT2</b>: efectos opuestos: vasodilatación, antiproliferativo, apoptosis.<br>Atribuir vasoconstricción y activación simpática al AT2 es falso."},
{t:2,q:"Los eicosanoides NO están indicados en:",o:["Profilaxis de úlcera gastroduodenal","Disminución de la presión intraocular","Coagulación intravascular diseminada","Incremento de la producción seminal"],a:2,m:0,
n:"Usos de los eicosanoides:<br>• Misoprostol (PGE1): profilaxis de úlcera por AINEs.<br>• Latanoprost (PGF2α): baja la PIO en glaucoma.<br>• PGF2α: luteólisis, sincronización del celo, inducción del parto y aumento de la producción seminal (toros, verracos).<br>No se usan en la <b>CID</b>: eicosanoides como el tromboxano A2 favorecen la agregación plaquetaria."},
{t:3,q:"AINEs. Señalar la proposición incorrecta:",o:["La inhibición de COX-3 está relacionada con su actividad antipirética y analgésica","Paracetamol y dipirona son potentes antiinflamatorios","No son efectivos para controlar la hipertermia inducida por ejercicio excesivo o aplicación de PGE2","La inhibición de la COX-1 es la responsable de los efectos adversos de estos fármacos"],a:1,d:true,
n:"Paracetamol y metamizol (dipirona) son buenos analgésicos y antipiréticos pero <b>antiinflamatorios muy débiles</b> (actúan sobre todo a nivel central, COX-3). La inhibición de COX-1 explica la mayoría de los efectos adversos (gástricos, renales, plaquetarios). No bajan la hipertermia por ejercicio ni la provocada por PGE2 exógena.<br>En otra versión de esta pregunta la afirmación falsa es «Son efectivos para controlar la hipertermia inducida por ejercicio excesivo o por aplicación de PGE2»: no lo son.<br><b>Ojo, según tus apuntes (actualización 2025/2026):</b> la profesora explica que en humanos la COX-3 no existe como enzima funcional y que se descarta que el paracetamol actúe por ella. Esta pregunta es de exámenes anteriores, que daban la COX-3 por buena; si este año aparece, la afirmación sobre la COX-3 también podría considerarse falsa."},
{t:3,q:"Farmacocinética de AINEs. Señalar la correcta:",o:["Presentan volúmenes de distribución elevados","Su eliminación en orina depende del pH y la tasa de secreción tubular","No se biotransforman","Se acumulan en tejidos inflamados por su baja tasa de unión a proteínas plasmáticas"],a:1,
n:"Los AINEs son ácidos débiles con <b>alta unión a proteínas</b> (>90 %) → volumen de distribución <b>bajo</b>. Se acumulan en el foco inflamatorio (pH ácido y extravasación de proteínas). Se biotransforman en el hígado. Su eliminación urinaria depende del <b>pH</b> (la orina alcalina aumenta la excreción) y de la <b>secreción tubular</b> activa."},
{t:3,q:"¿Cuál de los siguientes fármacos es un agente biológico modificador de la enfermedad anti-TNF utilizado en artritis reumatoide?",o:["Rituximab","Tofacitinib","Etanercept","Leflunomida"],a:2,
n:"Anti-TNF biológicos: <b>etanercept</b> (proteína de fusión con el receptor del TNF), infliximab, adalimumab.<br>• Rituximab: anti-CD20 (linfocitos B).<br>• Tofacitinib: inhibidor de JAK (FAME sintético dirigido).<br>• Leflunomida: FAME sintético convencional (inhibe la síntesis de pirimidinas)."},
{t:4,q:"¿Cuál de los siguientes efectos NO es producido por los glucocorticoides?",o:["Aumento de la volemia e hipertensión","Aumento de neutrófilos y plaquetas","Estimulación de la gluconeogénesis a nivel hepático","Disminución de la eliminación urinaria de ácido úrico"],a:3,m:1,
n:"Los glucocorticoides <b>aumentan</b> la eliminación urinaria de ácido úrico (efecto uricosúrico).<br>Sí producen: retención de Na⁺ y agua (↑volemia, HTA); <b>neutrofilia</b> y aumento de plaquetas y eritrocitos, con linfopenia y eosinopenia («leucograma de estrés»); y estimulan la gluconeogénesis hepática."},
{t:2,q:"Usos de antihistamínicos. Señalar la proposición FALSA:",o:["Los antiH2 se pueden usar para el tratamiento de úlcera péptica y gastritis urémica","Los antiH3 se usan en deterioro cognitivo y desórdenes del sueño","Los antiH1 se usan para evitar retención de placenta","Los antiH2 se usan para el tratamiento de vómitos y vértigo"],a:3,
n:"Para vómitos por cinetosis y vértigo se usan <b>antiH1</b> (dimenhidrinato, meclizina, difenhidramina), no antiH2.<br>• AntiH2: úlcera péptica, gastritis urémica, esofagitis por reflujo.<br>• AntiH3: deterioro cognitivo y trastornos del sueño.<br>• AntiH1 en veterinaria: alergias, prurito y coadyuvante en retención de placenta."},
{t:2,q:"Los antihistamínicos H1 presentan buena eficacia EXCEPTO en:",o:["Urticaria y prurito","Broncoespasmo","Retención de placenta","Rinitis y conjuntivitis alérgica"],a:1,
n:"En el broncoespasmo y el asma participan muchos otros mediadores (leucotrienos, etc.), por eso los antiH1 son <b>poco eficaces</b>. Funcionan bien en urticaria, prurito, rinitis y conjuntivitis alérgica.<br>En otra versión («Aplicaciones terapéuticas de los antiH1. Señala la incorrecta») aparece además «Coadyuvantes de la adrenalina y los glucocorticoides en la anafilaxia», que es una aplicación correcta; la incorrecta sigue siendo el broncoespasmo."},
{t:2,q:"Toxicidad de la metoclopramida. ¿Cuál NO es un efecto tóxico provocado por este fármaco?",o:["Trastornos del movimiento","Estreñimiento","Galactorrea","Somnolencia y fatiga"],a:1,
n:"Metoclopramida: antagonista D2 (y 5-HT3) y agonista 5-HT4 → procinético y antiemético. Al aumentar la motilidad provoca <b>diarrea</b>, no estreñimiento. Otros efectos: trastornos extrapiramidales del movimiento, galactorrea (↑prolactina por bloqueo D2), somnolencia y fatiga."},
{t:2,q:"Antagonistas 5-HT3. Señalar la proposición CORRECTA:",o:["Pueden provocar broncoespasmo e hipotensión","La vía intravenosa está contraindicada","Antagonizan los receptores dopaminérgicos D2","Muy eficaces contra vómitos de origen cinético"],a:0,
n:"Setrones (ondansetrón, granisetrón): bloquean los 5-HT3 de la zona gatillo y de las aferencias vagales. Muy eficaces en vómitos por quimioterapia, <b>poco en cinetosis</b>. Se pueden dar por vía IV y no bloquean D2. Reacciones adversas poco frecuentes: hipersensibilidad con <b>broncoespasmo e hipotensión</b>, estreñimiento, cefalea.<br>En otra versión de esta pregunta la opción correcta dice «Pueden provocar hipotensión y bradicardia», que también es cierta."},
{t:2,q:"Características farmacológicas de antihistamínicos H1. Señalar la proposición FALSA:",o:["Los de 2ª generación presentan menos incompatibilidades por ser metabolizados por enzimas microsomales","Poseen una acción poco selectiva","Los de 1ª generación presentan mayor probabilidad de bloqueo de receptores autonómicos","Los de 2ª generación presentan menor penetración y por tanto menores efectos sedantes"],a:0,
n:"Precisamente por metabolizarse por el citocromo P450 (CYP3A4), los de 2ª generación presentan <b>MÁS interacciones</b> (con macrólidos e imidazoles → cardiotoxicidad de terfenadina y astemizol). Los de 1ª generación son poco selectivos (bloqueo colinérgico y α) y atraviesan la BHE (sedación)."},
{t:2,q:"Efectos farmacológicos de la histamina. Señalar la proposición FALSA:",o:["Disminuye la conducción auriculoventricular","En perro produce vasodilatación de venas hepáticas","Disminuye la resistencia vascular periférica","Produce vasoconstricción de vasos de gran calibre"],a:1,
n:"En el perro la histamina produce <b>constricción</b> de las venas hepáticas (acumulación de sangre en el territorio esplácnico, típico del shock anafiláctico canino). Además disminuye la conducción AV, baja la RVP (dilata los vasos pequeños) y contrae los vasos de gran calibre."},
{t:2,q:"La activación de receptores H1 de la histamina produce (señalar la CORRECTA):",o:["Bradicardia","Activa la secreción de catecolaminas en médula adrenal","Relajación de la musculatura gástrica","Broncodilatación"],a:1,
n:"Efectos H1: contracción del músculo liso (bronquios → <b>broncoconstricción</b>, intestino), vasodilatación de vasos pequeños con aumento de permeabilidad, prurito y dolor, y <b>liberación de catecolaminas en la médula adrenal</b>. La taquicardia y el aumento de contractilidad dependen de H2."},
{t:2,q:"¿Cuál NO es un efecto farmacológico de la serotonina?",o:["Efecto cronotropo e inotropo negativo","Vasoconstricción arteriolar en músculo esquelético y cardiaco","Broncoconstricción","Disminución de la agresividad"],a:1,m:0,d:true,
n:"La serotonina contrae la mayoría de los vasos (grandes arterias, venas), pero <b>DILATA las arteriolas del músculo esquelético y del corazón</b> (vía óxido nítrico endotelial). En el corazón su efecto directo es crono e inotropo positivo, aunque puede producir bradicardia refleja (reflejo de Bezold-Jarisch, 5-HT3), por eso la opción A es discutible. Además produce broncoconstricción y a nivel central reduce la agresividad.<br>En otras versiones de esta pregunta aparece «cronotropo e inotropo <b>positivo</b>» (y la respuesta es claramente la vasoconstricción arteriolar) o «<b>vasodilatación</b> arteriolar en músculo esquelético y cardiaco» (y entonces la respuesta es el efecto cronotropo e inotropo negativo)."},
{t:2,q:"Señalar la proposición INCORRECTA:",o:["COX-2 es inducible y promueve la formación de mediadores proinflamatorios","La 5-lipooxigenasa produce leucotrienos a partir de ácido araquidónico implicados en shock anafiláctico y asma","COX-1 es una enzima constitutiva muy implicada en la síntesis de prostanoides para la homeostasis del organismo","Los leucotrienos A4 y B4 poseen cisteína y componen la sustancia de reacción lenta de la anafilaxia"],a:3,
n:"Los leucotrienos con cisteína (cisteinil-LT) son <b>LTC4, LTD4 y LTE4</b>: forman la sustancia de reacción lenta de la anafilaxia (SRS-A). LTA4 es el precursor inestable y LTB4 es quimiotáctico; ninguno lleva cisteína. COX-1 es constitutiva (homeostasis), COX-2 inducible (inflamación) y la 5-LOX produce leucotrienos."},
{t:2,q:"Acciones de la angiotensina II. Señalar la INCORRECTA:",o:["En SNC provoca aumento del tono simpático que provoca aumento de la resistencia periférica y del gasto cardiaco","Aumento de la diuresis","A nivel cardiaco provoca efecto crono e inotropo positivos","Induce a nivel cardiovascular expresión de genes que conducen a remodelación del sistema"],a:1,
n:"La angiotensina II es <b>antidiurética</b>: retiene Na⁺ y agua (directamente en el túbulo proximal y a través de aldosterona y ADH). Además aumenta el tono simpático central, tiene efecto crono e inotropo positivo y produce remodelación cardiovascular."},
{t:3,q:"Reacciones adversas de AINEs. Señalar la INCORRECTA:",o:["Pueden provocar hiperuricemia e hipertensión","La tepoxalina en sobredosificación puede provocar fiebre y acúfenos","Pueden producir acidosis mixta respiratoria y metabólica","Son ulcerógenos y dificultan la reepitelización de la mucosa afectada"],a:1,
n:"Fiebre y acúfenos (tinnitus) por sobredosis son típicos del <b>salicilismo</b> (ácido acetilsalicílico), no de la tepoxalina. Los AINEs pueden dar hiperuricemia (salicilatos a dosis bajas), HTA (retención de Na⁺), acidosis mixta (salicilatos) y son ulcerógenos (retrasan la reepitelización).<br>Una de las claves de clase marca la de hiperuricemia e hipertensión, pero las otras dos coinciden con esta respuesta: los AINEs sí pueden provocarlas."},
{t:3,q:"Sobre la actividad antiinflamatoria de AINEs. Señalar la afirmación INCORRECTA:",o:["Las concentraciones necesarias para reducir la inflamación son inferiores a las que inhiben la actividad de la COX","Los fenamatos poseen una acción más rápida pues pueden antagonizar PGs ya presentes en el foco inflamatorio, pero no impiden la liberación de radicales libres","Diflunisal y tepoxalina pueden inhibir la 5-lipooxigenasa","La acción antiinflamatoria es estereoespecífica en los derivados del ácido propiónico"],a:0,
n:"Las concentraciones necesarias para el efecto antiinflamatorio son <b>SUPERIORES</b> a las que inhiben la COX (por eso las dosis antiinflamatorias son más altas que las analgésicas, y se proponen mecanismos adicionales).<br>• Fenamatos: inhiben la síntesis y además antagonizan PGs ya formadas → acción más rápida.<br>• Tepoxalina (y diflunisal) inhiben también la 5-LOX.<br>• En los derivados del ácido propiónico la actividad reside en el enantiómero S."},
{t:3,q:"¿Cuál de las siguientes proposiciones sobre la toxicidad de los AINEs es INCORRECTA?",o:["Generan reducción del flujo sanguíneo y de la tasa de filtración a nivel renal","Los análogos de las PGs como el misoprostol son útiles para la profilaxis de úlceras gástricas por AINEs","La inhibición a nivel del aparato yuxtaglomerular origina una actividad del sistema renina-angiotensina-aldosterona aumentada","Nimesulida y nabumetona presentan actividad ulcerógena baja"],a:2,
n:"Las prostaglandinas estimulan la liberación de renina. Al inhibirlas, los AINEs <b>DISMINUYEN</b> la actividad del sistema renina-angiotensina-aldosterona (hipoaldosteronismo hiporreninémico → hiperpotasemia). También reducen el flujo renal y la FG. El misoprostol previene úlceras por AINEs; nimesulida y nabumetona son poco ulcerógenas."},
{t:4,q:"Receptor glucocorticoide. Señalar la proposición INCORRECTA:",o:["Por unión del receptor con la proteína AP-1 y el factor nuclear kappa B se inhibe la expresión de genes que codifican proteínas inflamatorias","La activación de la expresión de genes requiere la unión del receptor con el ADN en elementos de respuesta a GC (GRE) y da lugar a síntesis de proteínas antiinflamatorias","La zona amino-terminal del receptor interacciona con los esteroides y modula la formación de dímeros","La zona central con sus residuos de cinc se une al ADN nuclear"],a:2,
n:"Dominios del receptor GC:<br>• <b>C-terminal</b>: unión al ligando (esteroide) y a las proteínas de choque térmico (HSP90); interviene en la dimerización.<br>• <b>Central</b>: unión al ADN mediante «dedos de cinc».<br>• <b>N-terminal</b>: dominio de transactivación.<br>Transactivación: unión a GRE → proteínas antiinflamatorias (lipocortina). Transrepresión: interacción con AP-1 y NF-κB → inhibe genes proinflamatorios."},
{t:3,q:"Señalar la proposición CORRECTA sobre antiartríticos:",o:["Los GAGs tienen poca utilidad en el desgaste articular por sobrepeso y tras traumatismo","Para apreciar los efectos beneficiosos de los GAGs se necesitan al menos 3-4 semanas y deben aplicarse cíclicamente en casos de artrosis","El ácido hialurónico se administra preferentemente vía intramuscular","El hialurónico reduce la infiltración de PMN y la pérdida de GAGs"],a:3,d:true,
n:"El ácido hialurónico se administra por vía <b>intraarticular</b> (o IV), no IM. Mejora la viscosidad del líquido sinovial, <b>reduce la infiltración de PMN</b>, los radicales libres y la <b>pérdida de glucosaminoglicanos (GAGs)</b>. Los condroprotectores (GAGs polisulfatados, condroitín, glucosamina) sí son útiles en la artrosis por sobrepeso y postraumática.<br>Ojo: otra clave de clase marca la de los GAGs (al menos 3-4 semanas y en ciclos en la artrosis), que también es cierta: son condroprotectores de acción lenta. En ese PDF aparecen como «GCG»."},
{t:4,q:"Farmacocinética de glucocorticoides. Señalar la INCORRECTA:",o:["Su biotransformación se realiza exclusivamente a nivel hepático","A nivel intraarticular se usan ésteres o suspensiones de absorción más reducida","La eliminación es mayoritariamente renal, eliminándose también en heces y vía mamaria","La vía tópica permite alcanzar concentraciones elevadas en piel y mucosas disminuyendo riesgos sistémicos"],a:0,
n:"Se biotransforman principalmente en el hígado, pero <b>no exclusivamente</b>: también en riñón y otros tejidos (11β-HSD). Eliminación mayoritariamente renal (también heces y leche). Intraarticular: ésteres o suspensiones de absorción lenta (depot). Tópica: altas concentraciones locales con menos riesgo sistémico."},
{t:5,q:"Dobutamina. Señalar la proposición INCORRECTA:",o:["En taquicardias supraventriculares asociar a digitálicos","A dosis elevadas puede provocar taquiarritmias por ser proarritmogénica","Utilizada en ICC en infusión continua a dosis bajas","Agonista beta adrenérgico que posee menor acción inotrópica que vasodilatadora"],a:3,
n:"Dobutamina: agonista β1 (con algo de β2 y α1) con acción <b>inotrópica predominante</b> y poco efecto sobre la frecuencia y la resistencia vascular. Se usa en infusión continua IV (vida media de minutos). A dosis altas: taquiarritmias. En fibrilación o taquicardia supraventricular se digitaliza antes, porque facilita la conducción AV.<br>En otra versión, la opción de la infusión a dosis bajas añade «para controlar la hipertensión», y entonces también sería falsa: la dobutamina no se usa para eso."},
{t:5,q:"Pimobendan. Señalar la proposición INCORRECTA:",o:["Inodilatador dual indicado en ICC por insuficiencia valvular","Su metabolito produce la acción vasodilatadora por inhibición de PDE III y V","Disminuye la hipertrofia cardiaca patológica","Se asocia a beta-bloqueantes para contrarrestar su efecto proarrítmico"],a:3,
n:"Pimobendan: inodilatador (sensibiliza la troponina C al Ca²⁺ e inhibe PDE3; su metabolito ODMP inhibe PDE III/V → vasodilatación). Indicado en ICC por endocardiosis mitral y cardiomiopatía dilatada en perro. <b>No se asocia a β-bloqueantes</b> (tienen efectos opuestos sobre la contractilidad); se combina con IECA, diuréticos y espironolactona."},
{t:5,q:"Inhibidores de PDE (amrinona). Señalar la proposición CORRECTA:",o:["Pueden provocar disritmias ventriculares y trombocitopenia","Amrinona presenta escaso metabolismo hepático y se elimina mayoritariamente vía renal en forma activa","Su utilización aumenta el consumo de oxígeno a nivel cardiaco","Controlan la ICC a largo plazo y poseen más acción inotrópica que vasodilatadora"],a:0,
n:"Amrinona y milrinona: inhibidores de PDE3, inodilatadores de uso a <b>corto plazo</b> (en tratamiento crónico aumentan la mortalidad). Efectos adversos: <b>arritmias ventriculares y trombocitopenia</b> (amrinona). Apenas aumentan el consumo de O₂. La amrinona tiene un metabolismo hepático importante (acetilación).<br>En otra versión aparece «Posee una semivida adecuada para administrarlas en bolo intravenoso», también falsa: tienen semivida corta y se dan en infusión continua (tras una dosis de carga)."},
{t:5,q:"¿Cuál NO es una reacción adversa de los digitálicos?",o:["Visión borrosa y discromatopsia","Convulsiones","Arritmias, extrasístoles y/o bloqueo AV","Dolor abdominal, vómitos o náuseas"],a:1,
n:"Intoxicación digitálica:<br>• Digestivos (los primeros): anorexia, náuseas, vómitos, dolor abdominal, diarrea.<br>• Cardiacos: extrasístoles, bloqueo AV, taquiarritmias.<br>• Neurológicos y visuales: letargia, desorientación, visión borrosa, discromatopsia.<br>Las <b>convulsiones</b> no son una reacción característica."},
{t:5,q:"Inhibidores de fosfodiesterasas (IPDE). Señalar la proposición INCORRECTA:",o:["Aumentan la perfusión orgánica al disminuir la resistencia vascular sistémica","Los inhibidores de PDE5 como el sildenafilo son útiles para reducir la hipertensión pulmonar en perro","Los inhibidores de PDE3 son útiles para el tratamiento a corto plazo del fallo cardiaco o la descompensación de IC crónica","A nivel cardiaco disminuyen la contractilidad y la frecuencia"],a:3,m:1,
n:"A nivel cardiaco los inhibidores de PDE3 <b>AUMENTAN la contractilidad</b> (y pueden aumentar la frecuencia). Reducen la RVS → mejor perfusión. El sildenafilo (PDE5) <b>sí es útil</b> en la hipertensión pulmonar del perro.<br>En otra versión, la opción de la PDE3 dice «como el cilostazol». Ojo: el cilostazol es un inhibidor de la PDE3 antiagregante y vasodilatador (claudicación intermitente) que no se usa en la insuficiencia cardiaca; la respuesta del examen sigue siendo la de la contractilidad."},
{t:2,q:"Acciones fisiológicas de los péptidos natriuréticos. Señalar la proposición INCORRECTA:",o:["Poseen actividad antiproliferativa y antifibrótica","Producen vasodilatación arterial y venosa","Producen inhibición de la endotelina I","Estimulan la liberación de vasopresina"],a:3,m:2,
n:"Péptidos natriuréticos (ANP, BNP): natriuresis y diuresis, vasodilatación arterial y venosa, efecto antiproliferativo y antifibrótico. Inhiben la renina, la aldosterona, la endotelina-1 y la <b>liberación de vasopresina</b> (no la estimulan)."},
{t:5,q:"Antagonistas del calcio derivados de dihidropiridina (amlodipino…). Señalar la proposición CORRECTA:",o:["Son arteriodilatadores no vasoselectivos","Utilizados en hipertensión y espasmos vasculares en hemorragias subaracnoideas","Contraindicados en profilaxis y crisis agudas de infarto porque pueden provocar espasmo de coronarias","No provocan taquicardia refleja"],a:1,
n:"Dihidropiridinas (nifedipino, amlodipino, nimodipino): arteriodilatadores <b>vasoselectivos</b>, con poco efecto sobre el corazón, por lo que producen <b>taquicardia refleja</b>. Usos: hipertensión (amlodipino en gatos) y vasoespasmo tras hemorragia subaracnoidea (nimodipino)."},
{t:5,q:"Antagonistas del calcio, cationes anfófilos. Señalar la proposición INCORRECTA:",o:["Producen efecto cronotropo y dromotropo negativo","Útiles en hipertensión y cardiomiopatía hipertrófica felina","Son arteriodilatadores no vasoselectivos","Contraindicados en daño cerebral provocado por traumatismos"],a:3,
n:"Verapamilo y diltiazem (cationes anfófilos) actúan sobre corazón y vasos (<b>no vasoselectivos</b>): cronotropo y dromotropo negativos. Usos: hipertensión, taquicardias supraventriculares y cardiomiopatía hipertrófica felina (diltiazem). No están contraindicados en el daño cerebral traumático."},
{t:2,q:"Antihistamínicos H1 de 2ª generación. Señalar la proposición FALSA:",o:["La excreción es fundamentalmente hepática","Al ser metabolizados por el citocromo CYP3A4 presentan interacciones con otros fármacos de similar metabolismo","Presentan una unión elevada a proteínas plasmáticas","Algunos poseen metabolitos con lo que se prolonga su acción"],a:0,
n:"La excreción de los antiH1 de 2ª generación es fundamentalmente <b>RENAL</b>. Se metabolizan por CYP3A4 (interacciones con macrólidos, imidazoles…), tienen alta unión a proteínas y algunos generan metabolitos activos (p. ej. loratadina → desloratadina) que prolongan su acción."},
{t:2,q:"Serotonina. Señalar la proposición FALSA:",o:["La excreción se produce a nivel renal","Su biotransformación se produce exclusivamente en hígado","Se almacena en células enterocromafines y plaquetas","En glándula pineal es precursora de melatonina"],a:1,
n:"La serotonina se metaboliza por la MAO (→ ácido 5-hidroxiindolacético, 5-HIAA) en hígado, <b>pulmón, endotelio y otros tejidos</b>: no exclusivamente en hígado. Se excreta por riñón. Se almacena en células enterocromafines (~90 %), plaquetas y neuronas. En la glándula pineal es precursora de la melatonina."},
{t:2,q:"Interacciones de antihistamínicos H1. Señalar la proposición FALSA:",o:["Potencian la acción de anticolinérgicos","Potencian la acción sedante de analgésicos opiáceos","Pueden presentar cardiotoxicidad (astemizol) si se usan con macrólidos o imidazoles","Aumentan el efecto de corticosteroides"],a:3,
n:"Interacciones de los antiH1 (sobre todo 1ª generación): potencian los <b>anticolinérgicos</b> y los <b>depresores del SNC</b> (opiáceos, alcohol, hipnóticos). Terfenadina y astemizol + macrólidos o imidazoles (inhiben CYP3A4) → arritmias graves. <b>No aumentan</b> el efecto de los corticosteroides."},
{t:2,q:"Los agonistas de la serotonina NO se usan para el tratamiento de:",o:["La ansiedad","Comportamientos compulsivos y automutilación","Vómitos","Atonía ruminal y reflujo gastroesofágico"],a:2,d:true,
n:"Usos de agonistas o potenciadores serotoninérgicos: ansiedad (buspirona, 5-HT1A), conductas compulsivas y automutilación (ISRS como fluoxetina, clomipramina), procinéticos en atonía ruminal y reflujo (agonistas 5-HT4: cisaprida). Para los vómitos se usan <b>antagonistas 5-HT3</b>.<br>Ojo: otra clave de clase marca «comportamientos compulsivos y automutilación», porque se tratan con ISRS (fluoxetina, clomipramina), que aumentan la serotonina de forma indirecta pero no son agonistas directos. La respuesta más defendible es la de los vómitos: para el vómito se usan antagonistas 5-HT3."},
{t:2,q:"Los eicosanoides se caracterizan por (señalar la correcta):",o:["Tener estructura glucídica","Almacenarse en células específicas","Amplia presencia en el organismo excepto eritrocitos","Ser los autacoides con menos potencia"],a:2,
n:"Eicosanoides: derivados de ácidos grasos de 20 C (ácido araquidónico) → estructura <b>lipídica</b>. <b>No se almacenan</b>: se sintetizan a demanda. Los producen casi todas las células <b>excepto los eritrocitos</b>. Son autacoides muy potentes, de acción local."},
{t:2,q:"¿Cuál de los siguientes efectos NO es provocado por la angiotensina II?",o:["Aumento de la producción de radicales superóxido y agregación plaquetaria","El incremento del tono simpático a nivel de SNC provoca hipertensión","Inhibición de la liberación de ADH y ACTH","Liberación de adrenalina y aldosterona por estimulación de la glándula adrenal"],a:2,
n:"La angiotensina II <b>estimula</b> la liberación de ADH (vasopresina) y ACTH, y provoca sed. También aumenta los superóxidos y la agregación plaquetaria, eleva el tono simpático central y libera adrenalina y aldosterona de la glándula adrenal."},
{t:3,q:"Actividad analgésica de AINEs. Señalar la INCORRECTA:",o:["Actividad antiálgica de intensidad moderada o media","Presenta gran variabilidad en la respuesta individual y no producen tolerancia","Útil para dolores inducidos por estimulación mecánica o eléctrica","Asociada a la capacidad de inhibir la síntesis de PGs por la COX"],a:2,
n:"Los AINEs son analgésicos de intensidad leve-moderada, útiles en el <b>dolor inflamatorio</b> (las PGs sensibilizan los nociceptores). <b>No son eficaces</b> en el dolor por estimulación mecánica o eléctrica directa ni en el dolor visceral intenso. Gran variabilidad individual; no producen tolerancia ni dependencia."},
{t:2,q:"¿Cuál de las siguientes NO es una indicación para el uso de eicosanoides en veterinaria?",o:["Sincronización del celo","Disminución de la PIO en glaucoma","Inducción al parto","Procinéticos en atonía ruminal"],a:3,
n:"PGF2α (dinoprost, cloprostenol): sincronización del celo, inducción del parto o aborto, piómetra. Latanoprost: glaucoma (↓PIO). Misoprostol: protección gástrica. <b>No se usan como procinéticos</b> en la atonía ruminal."},
{t:5,q:"Señalar la proposición INCORRECTA sobre los SARTANES:",o:["Favorecen la retención de agua y sodio","Son antagonistas puros del receptor AT1 de uso oral","Sustituyen adecuadamente a los IECAs cuando aparece tos seca en el paciente","Tienen efecto antiproliferativo y antiapoptótico"],a:0,
n:"ARA-II (losartán, telmisartán, valsartán): antagonistas selectivos del receptor AT1, por vía oral. Al bloquear la angiotensina II y la aldosterona favorecen la <b>excreción</b> de agua y Na⁺ (no la retención). No elevan la bradicinina → no dan tos seca, por eso sustituyen a los IECA. Telmisartán: proteinuria en gatos."},
{t:3,q:"¿Cuál de los siguientes fármacos es un modificador de la enfermedad sintético dirigido utilizado en la artritis reumatoide?",o:["Tofacitinib","Rituximab","Abatacept","Leflunomida"],a:0,m:3,d:true,
n:"FAME <b>sintéticos dirigidos</b> (tsDMARD): inhibidores de JAK (<b>tofacitinib</b>, baricitinib; en veterinaria, oclacitinib).<br>• FAME biológicos: rituximab (anti-CD20), abatacept (bloquea la coestimulación de linfocitos T), anti-TNF.<br>• Leflunomida y metotrexato son FAME sintéticos <b>convencionales</b>.<br>Ojo: dos claves de clase marcan la leflunomida. Según la clasificación actual, la leflunomida es un FAME sintético <b>convencional</b> y el tofacitinib (inhibidor JAK) el sintético <b>dirigido</b>; en otra clave de clase también se anota la leflunomida como «convencional (sintético)». Si tu profesora dio por buena la leflunomida, prioriza su criterio."},
{t:5,q:"Señalar la proposición INCORRECTA sobre los bloqueantes beta-adrenérgicos:",o:["Estabilizan membranas y enlentecen la conducción AV","Carvedilol y propranolol, al no ser selectivos β1, pueden provocar broncoconstricción","Pueden incrementar la aparición de despolarizaciones prematuras","Pueden reducir la presión sanguínea en hipertensión"],a:2,
n:"Los β-bloqueantes (clase II) <b>DISMINUYEN</b> el automatismo y las despolarizaciones prematuras o ectópicas, enlentecen la conducción AV y estabilizan membranas (propranolol). Los no selectivos (propranolol, carvedilol) bloquean β2 → broncoconstricción. Reducen la presión arterial en la hipertensión."},
{t:5,q:"IECAs. Señalar la proposición CORRECTA:",o:["Promueven natriuresis y diuresis","Todas son ciertas","Útiles en profilaxis y tratamiento de cardiopatía isquémica","Evitan la hipertrofia cardiaca y vascular en hipertensos"],a:1,
n:"IECA (enalapril, benazepril): al reducir angiotensina II y aldosterona → <b>natriuresis y diuresis</b>; son antiproliferativos → <b>evitan la hipertrofia</b> cardiaca y vascular; útiles en profilaxis y tratamiento de la <b>cardiopatía isquémica</b>, ICC, hipertensión y proteinuria renal. Todas las opciones son ciertas."},
{t:5,q:"Hidralazina. Señalar la proposición CORRECTA:",o:["De elección en tratamiento crónico de hipertensión asociada a insuficiencia renal grave","Muy utilizada junto a beta-bloqueantes y diuréticos","A altas dosis puede provocar bradicardia por acción vagolítica","Posee una vida media prolongada que facilita el cumplimiento de los tratamientos"],a:1,
n:"Hidralazina: arteriodilatador directo. Produce <b>taquicardia refleja</b> y retención de Na⁺ y agua, por eso se asocia a <b>β-bloqueantes y diuréticos</b>. Vida media corta (aunque su efecto dura más). Uso en perros: insuficiencia mitral e hipertensión."},
{t:2,q:"¿Cuál NO es un efecto farmacológico de los antihistamínicos H2?",o:["Algunos estimulan la secreción de prolactina","Estimulan el sistema microsomal hepático","Inhiben la vasodilatación e hipotensión","Presentan efecto antiandrogénico"],a:1,
n:"La cimetidina <b>INHIBE</b> el sistema microsomal hepático (citocromo P450) → muchas interacciones. Algunos (cimetidina) estimulan la prolactina y tienen efecto antiandrogénico. Bloquean el componente H2 de la vasodilatación e hipotensión por histamina."},
{t:5,q:"Los IECAs NO son útiles en:",o:["Insuficiencia cardiaca congestiva dilatada, hipertrófica y restrictiva","Glomerulopatías que cursen con oliguria","Nefropatía diabética","Insuficiencia renal progresiva"],a:1,
n:"Los IECA dilatan la arteriola eferente y reducen la presión de filtración: son útiles en proteinuria, nefropatía diabética e insuficiencia renal progresiva, pero en glomerulopatías con <b>oliguria</b> (o con hipovolemia o fallo renal agudo) pueden precipitar un fallo renal agudo. Son útiles en ICC por cardiomiopatía dilatada, hipertrófica y restrictiva."},
{t:3,q:"Farmacocinética de AINEs. Señalar la CORRECTA:",o:["Presentan volúmenes de distribución elevados","Existen variaciones en la vida media intra e interespecíficas","En general se unen poco a proteínas plasmáticas","No producen residuos en leche"],a:1,
n:"Hay grandes diferencias de vida media <b>entre especies</b> (ej. ácido acetilsalicílico: gato ≈ 38 h por déficit de glucuronidación, perro ≈ 8 h, caballo ≈ 1 h) e incluso entre individuos. Vd bajo, alta unión a proteínas y pueden dejar residuos en leche (tiempos de espera)."},
{t:3,q:"Actividad antipirética de los AINEs. Señalar la INCORRECTA:",o:["Diflunisal carece de esta actividad","Mediada por inhibición de COX-3 a nivel central","No producen hipotermia","Son efectivos para reducir la temperatura corporal anormalmente elevada por insolación o ejercicio intenso"],a:3,d:true,
n:"Los AINEs bajan la fiebre porque inhiben la síntesis de PGE2 en el hipotálamo (COX-3/COX-2 central). En la hipertermia por <b>golpe de calor o ejercicio</b> el punto de consigna hipotalámico no está alterado, por lo que <b>no son eficaces</b>. No producen hipotermia en animales normotérmicos. El diflunisal carece de acción antipirética.<br><b>Ojo, según tus apuntes (actualización 2025/2026):</b> la profesora explica que en humanos la COX-3 no existe como enzima funcional y que se descarta que el paracetamol actúe por ella. Esta pregunta es de exámenes anteriores, que daban la COX-3 por buena; si este año aparece, la afirmación sobre la COX-3 también podría considerarse falsa."},
{t:4,q:"¿Cuál de las siguientes reacciones adversas NO es producida por los glucocorticoides?",o:["Incrementan la incidencia de pancreatitis","Provocan anemia y neutropenia","Degeneración y atrofia muscular","Pueden provocar acné, alopecia y adelgazamiento de la piel"],a:1,
n:"Los GC producen <b>neutrofilia</b> (no neutropenia) y aumentan los eritrocitos (no anemia). Reacciones adversas: pancreatitis, atrofia muscular, piel fina, alopecia, comedones, Cushing iatrogénico, inmunosupresión, diabetes, úlceras, retraso de la cicatrización y supresión adrenal."},
{t:4,q:"Señalar la proposición INCORRECTA sobre los receptores GC y MC:",o:["La isoforma 1 de la enzima 11β-hidroxiesteroide deshidrogenasa convierte los corticoides fisiológicos en formas ceto inactivas en tejidos con capacidad de reacción mineralocorticoide","Aldosterona y cortisol se unen con igual afinidad al receptor mineralocorticoide","Los efectos rápidos como la excitabilidad neural y el comportamiento se explican por la interacción de GC con receptores específicos de membrana asociados a proteínas G","La aldosterona resiste la acción de la enzima por ser un derivado hemiacetal"],a:0,
n:"Es la <b>isoforma 2</b> (11β-HSD2) la que inactiva el cortisol a cortisona (forma 11-ceto) en los tejidos diana de mineralocorticoides (riñón, colon), protegiendo al receptor MC. La isoforma 1 hace lo contrario (reactiva cortisona → cortisol en hígado y tejido adiposo). Cortisol y aldosterona tienen igual afinidad por el receptor MC; la aldosterona resiste a la enzima por su estructura hemiacetal."},
{t:4,q:"De los siguientes fármacos, ¿cuál es la mejor opción para el tratamiento del hipercortisolismo o síndrome de Cushing en el perro?",o:["Ketoconazol","Aminoglutetimida","Trilostano","Mitotano"],a:2,
n:"<b>Trilostano</b>: inhibidor competitivo de la 3β-hidroxiesteroide deshidrogenasa → bloquea la síntesis de cortisol. Es el tratamiento de elección actual (registrado para perros) por eficacia y seguridad. Mitotano: adrenolítico (necrosis de las zonas fascicular y reticular), alternativa con más efectos adversos. Ketoconazol y aminoglutetimida son menos eficaces."},
{t:5,q:"Señalar la proposición CORRECTA sobre los glicósidos cardiotónicos:",o:["Aumentan el periodo refractario del nodo AV y la formación de impulsos ectópicos","Son útiles en IC grave asociada a hipertiroidismo","Son dromotropos y cronotropos positivos","Indicados en arritmias ventriculares en perro y gato"],a:0,m:2,
n:"Digitálicos: inotropos <b>positivos</b>, pero cronotropos y dromotropos <b>NEGATIVOS</b> (efecto vagal): aumentan el periodo refractario del nodo AV. A dosis altas aumentan el automatismo → impulsos ectópicos. Indicados en fibrilación auricular y taquicardias supraventriculares con ICC; poco útiles en IC por hipertiroidismo y contraindicados en arritmias ventriculares."},
{t:5,q:"Señalar la proposición CORRECTA sobre los bloqueantes de los canales de K⁺:",o:["El bretilio se utiliza para el control de fibrilación auricular en cardiomiopatía dilatada","Acortan el potencial de acción y el periodo refractario","Producen retraso en la repolarización","Amiodarona es de elección en taquicardias supraventriculares"],a:2,
n:"Clase III (amiodarona, sotalol, bretilio): bloquean canales de K⁺ → <b>retrasan la repolarización</b>, prolongan el potencial de acción y el periodo refractario. Bretilio: fibrilación <b>ventricular</b>. Amiodarona: arritmias ventriculares y supraventriculares refractarias (no es la de elección en TSV)."},
{t:5,q:"Efectos farmacológicos de los IECAs. Señalar la proposición INCORRECTA:",o:["Aumentan el flujo renal sin aumentar la tasa de filtración","Evitan la remodelación cardiaca tras una cardiopatía isquémica por ser antiproliferativos","Disminuyen la disfunción endotelial en enfermedad arterial e IC","Pueden provocar hipopotasemia"],a:3,
n:"Los IECA reducen la aldosterona → retienen K⁺: producen <b>HIPERpotasemia</b>, no hipopotasemia. Aumentan el flujo renal sin cambiar la FG, evitan la remodelación tras isquemia y mejoran la disfunción endotelial."},
{t:5,q:"Nitratos orgánicos. Señalar la respuesta INCORRECTA:",o:["Útiles en crisis agudas hipertensivas, en ICC e infarto","Pueden aumentar la demanda de oxígeno a nivel cardiaco","Para la profilaxis y tratamiento a largo plazo de la enfermedad coronaria es preferible utilizar nitratos orgánicos (mononitrato de isosorbida) que permiten su administración oral","Son vasodilatadores mixtos con más actividad sobre venas, por lo que disminuyen la precarga"],a:1,m:3,
n:"Los nitratos <b>DISMINUYEN</b> la demanda miocárdica de O₂ (↓precarga y poscarga → ↓tensión de la pared). Son vasodilatadores mixtos con predominio venoso (↓precarga). Útiles en crisis hipertensivas, ICC aguda e infarto; para el tratamiento crónico oral se usa mononitrato o dinitrato de isosorbida."},
{t:4,q:"Efectos de los glucocorticoides. Señalar la proposición CORRECTA:",o:["Aumentan la volemia por retención de agua","Disminuyen eritrocitos y plaquetas","A nivel vascular producen vasodilatación","Inhiben la actividad osteoclástica a nivel óseo"],a:0,m:1,
n:"GC: retención de Na⁺ y agua (<b>↑volemia</b>); <b>aumentan</b> eritrocitos y plaquetas; potencian la vasoconstricción por catecolaminas (efecto permisivo); en el hueso inhiben los osteoblastos y estimulan los osteoclastos → osteoporosis."},
{t:5,q:"Dopamina. Señalar la proposición INCORRECTA:",o:["En ICC congestiva se precisan dosis altas similares a las aplicadas en estados de shock","A dosis bajas puede ocasionar bradicardia e hipotensión por interacción con receptores D2","Vida media muy corta por lo que ha de administrarse IV","No puede usarse más de 72 h porque provoca desensibilización y disminución de receptores β1"],a:0,
n:"La dopamina es dosis-dependiente: dosis bajas → D1 (vasodilatación renal y esplácnica); intermedias → β1 (inotropo, uso en ICC); altas → α1 (vasoconstricción, shock). En la ICC se usan dosis <b>más bajas</b> que en el shock. Vida media de minutos → infusión IV. Desensibilización de receptores β1 tras ~72 h.<br>En otra versión, la opción de las dosis bajas añade «por lo que se utiliza para controlar la hipertensión arterial», y entonces también sería falsa: la dopamina no se usa para eso."},
{t:5,q:"Bloqueantes de los canales de Ca²⁺ (verapamilo). Señalar la proposición CORRECTA:",o:["Utilizados en intoxicación digitálica","Reducir la dosis en insuficiencia renal hasta un 70 %","Se pueden asociar con seguridad a beta-bloqueantes","De elección en taquicardias supraventriculares agudas"],a:3,
n:"Verapamilo: de elección en <b>taquicardias supraventriculares agudas</b> (enlentece el nodo AV). Contraindicado en la intoxicación digitálica. No asociar a β-bloqueantes (depresión cardiaca y bloqueo AV grave). Metabolismo hepático: se reduce la dosis en insuficiencia <b>hepática</b>, no renal."},
/* ---------- Preguntas añadidas del test de Daypo (1er parcial) ---------- */
{t:1,q:"El tratamiento de la diabetes con insulina es un tratamiento:",o:["Etiológico","Sintomático","Patogénico","Supresivo"],a:2,
n:"<b>Patogénico</b> (o correctivo): no elimina la causa (las células β siguen sin fabricar insulina), sino que corrige el mecanismo de la enfermedad aportando la hormona que falta; por eso también se le llama <b>sustitutivo</b>. Es de por vida.<br>• Etiológico o curativo: actúa sobre la causa (antibiótico en una infección).<br>• Sintomático: solo alivia síntomas (analgésico, antitusígeno).<br>• Supresivo o paliativo: alivio pasajero sin eliminar la enfermedad."},
{t:2,q:"Histamina. Efecto sobre la fibra lisa NO vascular:",o:["Disminución del peristaltismo en animales no rumiantes","Relajación ruminorreticular","Contracción bronquial (broncoconstricción) en todas las especies","Contracción bronquial solo en asmáticos"],a:1,
n:"En los rumiantes la histamina produce <b>relajación (atonía) del retículo-rumen</b>, que contribuye a la parada ruminal de la acidosis láctica. En el resto del tubo digestivo <b>contrae</b> (↑ peristaltismo, H1). La broncoconstricción (H1) varía mucho entre especies (intensa en el cobaya, casi nula en la rata) y aparece también en individuos sanos, aunque los asmáticos son mucho más sensibles."},
{t:2,q:"Efectos cardiovasculares de la histamina. Señala la opción CORRECTA:",o:["Hipertensión, vasoconstricción de arteriolas y vénulas y aumento de la resistencia periférica","Efecto cronotropo e inotropo positivo y aumento de la permeabilidad vascular y capilar","Efecto cronotropo e inotropo positivo, hipertensión y aumento de la resistencia periférica","Aumento de la permeabilidad capilar y vasoconstricción de arteriolas y vénulas"],a:1,
n:"En el test original había <b>varias respuestas correctas</b>; aquí van juntas en una sola opción.<br>✓ En el corazón la histamina es <b>crono e inotropa positiva</b> (receptores H2).<br>✓ <b>Aumenta la permeabilidad vascular y capilar</b> de las vénulas poscapilares (H1): edema y habón.<br>✗ No produce hipertensión ni aumenta la resistencia periférica: dilata los vasos pequeños → ↓ RVP e <b>hipotensión</b>.<br>✗ No contrae arteriolas ni vénulas; solo contrae los vasos de gran calibre."},
{t:2,q:"Efectos de la histamina. Señala la CORRECTA:",o:["Estimula las terminaciones nerviosas nociceptivas y aumenta la secreción gástrica","Relaja la musculatura bronquial y reduce la secreción gástrica de ácido","Contrae las arteriolas y aumenta la resistencia vascular periférica","Disminuye la permeabilidad capilar y alivia el prurito"],a:0,
n:"En el test original había dos respuestas correctas; aquí van juntas en una sola opción.<br>La histamina estimula las terminaciones nerviosas sensitivas: produce <b>dolor y prurito</b> (H1). En el estómago estimula la secreción de HCl a través de los receptores <b>H2</b> de las células parietales (por eso los antiH2 se usan en la úlcera). Además contrae los bronquios, dilata las arteriolas y aumenta la permeabilidad capilar."},
{t:2,q:"Receptores de la histamina. Señala la proposición INCORRECTA:",o:["El H1 está implicado en el aumento de permeabilidad y la migración leucocitaria","El H2 es de alta afinidad para la histamina y regula la secreción de renina","El H3 reduce la liberación de neurotransmisores y parece implicado en la esquizofrenia, la epilepsia y el dolor neuropático","El H4 modula la respuesta inmune y podría estar implicado en enfermedades autoinmunes"],a:1,
n:"Los receptores <b>H1 y H2 son de baja afinidad</b> (necesitan concentraciones altas de histamina); los de <b>alta afinidad son H3 y H4</b>.<br>• H2: secreción gástrica de ácido, efecto crono e inotropo positivo, parte de la vasodilatación.<br>• H3: presináptico en el SNC; frena la liberación de neurotransmisores.<br>• H4: células inmunes (quimiotaxis de eosinófilos y mastocitos)."},
{t:2,q:"Los antihistamínicos H1 pueden tener como efecto colateral:",o:["Ataxia y fatiga","Aumento del apetito","Sialorrea","Poliuria"],a:0,d:true,
n:"El efecto adverso más típico de los antiH1 (sobre todo de 1ª generación) es la <b>depresión del SNC</b>: sedación, somnolencia, fatiga, ataxia e incoordinación. Por su acción <b>anticolinérgica</b> producen sequedad de boca (no sialorrea) y retención urinaria (no poliuria). El aumento del apetito es propio de la ciproheptadina (que además bloquea la serotonina), no de los antiH1 en general.<br>Discutible: algunos antiH1 (ciproheptadina, astemizol) sí aumentan el apetito. Si tu profesor daba también por buena esa opción, la respuesta completa sería «ataxia, fatiga y aumento del apetito»."},
{t:2,q:"¿Cuál NO es un efecto de los antihistamínicos H1?",o:["Inhibir parcialmente la liberación de catecolaminas","Disminución del intervalo PR al aumentar la velocidad de conducción","Efecto depresor del SNC a dosis bajas y terapéuticas","Efecto anestésico local en nervios periféricos"],a:1,
n:"Los antiH1 no aceleran la conducción: a dosis altas tienen un efecto <b>tipo quinidina</b> que la <b>enlentece</b> (y algunos alargan el QT). Sí son efectos de los antiH1: sedación a dosis terapéuticas (1ª generación), <b>anestesia local</b> (difenhidramina, prometazina) e inhibición parcial de la liberación de catecolaminas de la médula adrenal, que la histamina estimula vía H1."},
{t:2,q:"Farmacocinética de los antihistamínicos H1. Señala la opción CORRECTA:",o:["No atraviesan la BHE y no poseen metabolitos activos","Tienen un elevado efecto de primer paso y su eliminación es renal","Tienen un elevado efecto de primer paso y no atraviesan la BHE","Su eliminación es renal y no poseen metabolitos activos"],a:1,
n:"En el test original había <b>varias respuestas correctas</b>; aquí van juntas en una sola opción.<br>✓ <b>Elevado efecto de primer paso</b>: se metabolizan mucho en el hígado (CYP3A4) en la primera pasada; la terfenadina casi desaparece en ella, y si se inhibe el CYP3A4 se acumula y da arritmias.<br>✓ Eliminación sobre todo <b>renal</b>.<br>✗ Los de 1ª generación sí atraviesan la BHE (sedación).<br>✗ Varios tienen <b>metabolitos activos</b>: loratadina → desloratadina, terfenadina → fexofenadina, hidroxicina → cetirizina.<br>En una clave de clase solo se marca el primer paso y se anota «eliminación fundamentalmente biliar»; en el examen de octubre de 2022, en cambio, se da por buena la excreción renal."},
{t:2,q:"Reacciones adversas de los antihistamínicos H1. Señala la FALSA:",o:["Depresión del SNC","Bradicardia","Discrasias sanguíneas","Actividad anticolinérgica, como sequedad de boca y de vías respiratorias altas"],a:1,
n:"Por su efecto anticolinérgico, los antiH1 tienden a producir <b>taquicardia</b>, no bradicardia; algunos (terfenadina, astemizol) alargan el QT y dan arritmias. Otras reacciones: sedación y depresión del SNC, sequedad de boca, retención urinaria, molestias digestivas y, raramente, discrasias sanguíneas (agranulocitosis, anemia hemolítica)."},
{t:2,q:"Efectos farmacológicos de los antihistamínicos H2. Señala la proposición INCORRECTA:",o:["Producen efecto cronotropo e inotropo negativo","Inhiben la vasodilatación e hipotensión","Algunos estimulan la secreción de prolactina (ginecomastia y galactorrea)","Inhiben el sistema microsomal hepático"],a:0,d:true,
n:"Los antiH2 <b>bloquean</b> el efecto crono e inotropo positivo de la histamina, pero por sí mismos no deprimen el corazón (solo en inyección IV rápida pueden dar bradicardia, de ahí la duda). También inhiben la parte de la vasodilatación e hipotensión mediada por H2. La <b>cimetidina</b> inhibe el citocromo P450 (interacciones) y aumenta la prolactina (ginecomastia, galactorrea)."},
{t:2,q:"Antihistamínicos H1 de 2ª generación. Señala la proposición INCORRECTA:",o:["Tienen, en general, vidas medias más prolongadas","Algunos poseen metabolitos con actividad antihistamínica","Presentan menor penetración en el SNC y son más selectivos","Tienen un metabolismo limitado"],a:3,
n:"Los antiH1 de 2ª generación (loratadina, terfenadina, astemizol…) sufren un <b>metabolismo hepático importante</b> por el CYP3A4: por eso interaccionan con macrólidos e imidazoles, y varios tienen metabolitos activos que alargan su acción. Atraviesan poco la BHE (apenas sedan), son más selectivos y tienen vidas medias largas (una dosis al día)."},
{t:2,q:"Antihistamínicos H2. Señala la opción CORRECTA:",o:["Producen hipertensión, mejoran la función renal y atraviesan la BHE, por lo que dan efectos centrales","Inhiben la secreción gástrica y el efecto crono e inotropo positivo cardiaco; se absorben poco por vía oral y sufren primer paso","Inhiben la secreción gástrica, disminuyen la secreción de prolactina y estimulan el sistema microsomal hepático","Sufren efecto de primer paso, se absorben poco por vía oral y se eliminan exclusivamente por vía hepática"],a:1,d:true,
n:"El original tenía 10 afirmaciones y <b>cuatro correctas</b> según la clave de clase; aquí van juntas.<br>✓ <b>Inhiben la secreción gástrica</b> de ácido (úlcera, gastritis urémica, reflujo).<br>✓ <b>Inhiben el efecto crono e inotropo positivo</b> de la histamina en el corazón (H2).<br>✓ <b>Se absorben poco por vía oral</b>: su biodisponibilidad oral es baja o moderada (en torno al 50 %), y por eso también se dan IM o IV, como anota la clave.<br>✓ <b>Sufren efecto de primer paso</b>.<br>✗ No producen hipertensión (solo bloquean la hipotensión mediada por H2) ni mejoran la función renal.<br>✗ La cimetidina <b>aumenta</b> la prolactina e <b>inhibe</b> el sistema microsomal.<br>✗ Apenas atraviesan la BHE y se eliminan sobre todo por el <b>riñón</b>."},
{t:2,q:"Antihistamínicos H2. Señala la proposición FALSA:",o:["No presentan efectos centrales","El 50 % se elimina en forma activa por vía renal","No presentan efecto de primer paso","Se biotransforman en menor medida que los antihistamínicos H1"],a:2,
n:"Los antiH2 se absorben bien por vía oral pero <b>sí sufren efecto de primer paso</b> (biodisponibilidad oral en torno al 50-70 %; la nizatidina casi no se metaboliza). Se biotransforman menos que los antiH1 y gran parte se elimina sin cambios por el riñón. Apenas atraviesan la BHE.<br>En otra versión de esta pregunta la opción del riñón dice «el 90 %»; la respuesta sigue siendo la del primer paso."},
{t:2,q:"Antihistamínicos H1 (2ª generación). Señala la INCORRECTA:",o:["Algunos poseen metabolitos con los que se prolonga su acción farmacológica","Apenas se unen a proteínas plasmáticas, con lo que los fenómenos de desplazamiento son mínimos","Tienen menor capacidad de penetración a través de la BHE","Se metabolizan por el citocromo CYP3A4, por lo que presentan interacciones con otros fármacos"],a:1,
n:"Los antiH1 de 2ª generación tienen una <b>unión elevada a proteínas plasmáticas</b> (más del 90 %), así que sí puede haber desplazamientos. El resto es cierto: metabolitos activos que alargan su acción, poco paso al SNC (apenas sedan) y metabolismo por el CYP3A4, que explica la cardiotoxicidad de terfenadina y astemizol junto a macrólidos o imidazoles."},
{t:2,q:"Cromoglicato sódico:",o:["Tiene valor profiláctico en la EPOC equina","Puede aumentar la reactividad bronquial","Tiene un margen terapéutico estrecho","Todas son ciertas"],a:0,
n:"El cromoglicato <b>estabiliza los mastocitos</b> e impide que liberen histamina y otros mediadores. Solo sirve de forma <b>preventiva</b> (inhalado antes de la exposición), por ejemplo en la obstrucción recurrente de las vías aéreas del caballo («EPOC equina» o asma equina). Reduce la reactividad bronquial y es muy seguro (amplio margen terapéutico)."},
{t:2,q:"Cromoglicato sódico. Señala la opción CORRECTA:",o:["Activa la fosfodiesterasa, reduciendo el AMPc, y antagoniza los receptores H1 y H2","Posee valor profiláctico pero no terapéutico, y es útil en el asma bronquial y alérgico","Posee valor profiláctico pero no terapéutico, y antagoniza los receptores H1 y H2","Es útil en el asma bronquial y alérgico, y activa la fosfodiesterasa, reduciendo el AMPc"],a:1,
n:"En el test original había <b>varias respuestas correctas</b>; aquí van juntas en una sola opción.<br>✓ Solo tiene valor <b>profiláctico</b>: estabiliza los mastocitos e impide su desgranulación, así que hay que darlo antes del contacto con el alérgeno; no sirve en plena crisis.<br>✓ Por eso es <b>útil en el asma bronquial y alérgico</b> (y en la EPOC o asma equina), como prevención.<br>✗ No activa la fosfodiesterasa (se le atribuyó lo contrario: inhibirla, con ↑ AMPc).<br>✗ No es antihistamínico: no bloquea H1 ni H2."},
{t:2,q:"Serotonina. Señala la FALSA:",o:["A bajas concentraciones tiene efectos estimulantes sobre el SNC","A altas concentraciones tiene efecto depresor sobre el SNC","Inhibe la liberación de ACTH","Estimula la contracción de la fibra muscular lisa","Es mediadora de la sensación dolorosa en el SNP"],a:2,
n:"La serotonina <b>estimula</b> la liberación de ACTH (a través de la CRH hipotalámica). Contrae la mayoría de las fibras lisas (bronquios, intestino, útero, vejiga, grandes vasos), estimula las terminaciones nerviosas sensitivas (dolor y prurito) y en el SNC estimula a concentraciones bajas y deprime a concentraciones altas."},
{t:2,q:"¿Cuál NO es un efecto de la serotonina?",o:["Contracción de la vejiga","Efecto cronotropo e inotropo positivo","Disminución de la actividad motora","Broncoconstricción"],a:2,
n:"La serotonina de las células enterocromafines <b>aumenta la motilidad</b> (actividad motora) del intestino y desencadena el reflejo peristáltico; un exceso (tumor carcinoide) da diarrea. Sí son efectos de la serotonina: contracción del músculo liso de la vejiga, los bronquios y el útero, y efecto crono e inotropo positivo directo en el corazón."},
{t:2,q:"Efectos farmacológicos de la serotonina:",o:["Midriasis","Efecto cronotropo negativo","Broncodilatación","Control neuroendocrino del sueño"],a:3,
n:"La serotonina participa en el <b>ciclo sueño-vigilia</b> (en la glándula pineal es precursora de la melatonina), además de en el apetito, el ánimo y la conducta (reduce la agresividad). En el corazón su efecto directo es crono e inotropo <b>positivo</b> y en los bronquios produce <b>broncoconstricción</b>."},
{t:2,q:"¿Cuál NO es un efecto farmacológico de la serotonina?",o:["Efecto cronotropo e inotropo negativo","Vasodilatación arteriolar en músculo esquelético y cardiaco","Broncoconstricción","Interviene en el control neuroendocrino del sueño"],a:0,
n:"El efecto directo de la serotonina sobre el corazón es <b>crono e inotropo positivo</b> (solo puede aparecer bradicardia refleja por el reflejo de Bezold-Jarisch, vía 5-HT3). Aunque contrae la mayoría de los vasos, <b>dilata las arteriolas del músculo esquelético y del corazón</b> (vía óxido nítrico endotelial). También produce broncoconstricción y participa en el control del sueño."},
{t:2,q:"Efectos de la serotonina. Señala la opción CORRECTA:",o:["Contracción de la vejiga urinaria e inhibición de la agregación plaquetaria","Contracción de la vejiga urinaria y dilatación del iris (midriasis)","Inhibición de la agregación plaquetaria y broncodilatación de las vías aéreas","Dilatación del iris y broncodilatación de las vías aéreas altas y bajas"],a:0,d:true,
n:"En el test original había <b>dos respuestas correctas</b> según la clave de clase; aquí van juntas en una sola opción.<br>✓ <b>Contracción de la vejiga urinaria</b>: contrae el músculo liso no vascular.<br>✓ <b>Inhibición de la agregación plaquetaria</b>: es la segunda que marca la clave (pregunta de 2 respuestas), y su autor anotó «en el hombre es agregante???». Ojo: en farmacología general la serotonina que liberan las plaquetas <b>favorece</b> la agregación (5-HT2A); quédate con lo que explique tu profesora.<br>✗ Según la clave, el iris se contrae (no se dilata), y en los bronquios produce <b>broncoconstricción</b>."},
{t:2,q:"Efectos farmacológicos de la serotonina. Señala la opción CORRECTA:",o:["Vasoconstricción arteriolar y venosa en cerebro y vísceras, y actividad antiagregante","Vasoconstricción arteriolar y venosa en cerebro y vísceras, y aumento de la agresividad","Actividad antiagregante y efecto cronotropo e inotropo negativo","Efecto cronotropo e inotropo negativo y aumento de la agresividad"],a:0,d:true,
n:"Con lo que marcan las claves de clase, en esta versión hay <b>dos opciones ciertas</b>; aquí van juntas.<br>✓ <b>Vasoconstricción</b> arteriolar y venosa en cerebro y vísceras (5-HT2).<br>✓ <b>Actividad antiagregante</b>: es la que marca la clave del examen de julio de 2021, donde la otra opción decía «vasodilatación» (falsa). Ojo: en farmacología general la serotonina es proagregante; quédate con lo que explique tu profesora.<br>✗ Es crono e inotropa <b>positiva</b> y <b>disminuye</b> la agresividad."},
{t:2,q:"Setrones (antagonistas 5-HT3). Señala la FALSA:",o:["No son eficaces en vómitos de origen cinético","Pueden provocar hipotensión y bradicardia a dosis elevadas","Son procinéticos","Son potentes antieméticos contra vómitos de origen central","Pueden administrarse por vía oral e intravenosa"],a:2,
n:"Los setrones (ondansetrón, granisetrón, dolasetrón) son antieméticos puros: bloquean los 5-HT3 de la zona gatillo y de las aferencias vagales, pero <b>no son procinéticos</b> (procinéticos son la metoclopramida y la cisaprida). Muy eficaces en el vómito por quimioterapia, poco en el de la cinetosis. Pueden darse por vía oral o IV."},
{t:2,q:"Antagonistas 5-HT3 (setrones). Señala la CORRECTA:",o:["Antagonizan los efectos eméticos de la serotonina solo a nivel central","Son eficaces en los vómitos por cinetosis","No se biotransforman y se eliminan por vía biliar","Pueden provocar como efectos adversos hipotensión y bradicardia"],a:3,
n:"Los setrones actúan <b>a nivel central</b> (zona gatillo quimiorreceptora) <b>y periférico</b> (aferencias vagales del intestino). Se metabolizan en el hígado y sus metabolitos se eliminan sobre todo por la orina. Efectos adversos poco frecuentes: <b>hipotensión y bradicardia</b> (sobre todo IV rápida), estreñimiento, cefalea. En la cinetosis van mejor el maropitant o los antiH1."},
{t:2,q:"¿Cuál de las siguientes proposiciones es INCORRECTA?",o:["La ciproheptadina puede ser útil en trastornos respiratorios en el gato","El sumatriptán es útil en la migraña y las cefaleas","La cisaprida se utiliza para trastornos severos de la motilidad","La cabergolina se usa para el tratamiento de las hemorragias posparto"],a:3,
n:"La <b>cabergolina</b> es un agonista dopaminérgico (derivado ergótico) que <b>inhibe la prolactina</b>: se usa en la pseudogestación y para cortar la lactancia, <b>no en hemorragias posparto</b> (ahí se usan oxitocina o ergometrina).<br>• Ciproheptadina: antagonista 5-HT2 y H1; asma felino y estimulante del apetito.<br>• Sumatriptán: agonista 5-HT1B/1D (migraña).<br>• Cisaprida: agonista 5-HT4, procinético (megacolon felino, reflujo)."},
{t:2,q:"¿Cuál es un agonista 5-HT4?",o:["Buspirona","Ondansetrón","Ketanserina","Cisaprida"],a:3,
n:"<b>Cisaprida</b> (y mosaprida, prucaloprida): agonistas 5-HT4 → liberan acetilcolina en el plexo mientérico → <b>procinéticos</b> (reflujo, megacolon felino, atonía ruminal). Buspirona: agonista 5-HT1A (ansiolítico). Ondansetrón: antagonista 5-HT3 (antiemético). Ketanserina: antagonista 5-HT2."},
{t:2,q:"Metoclopramida. Señala la proposición CORRECTA:",o:["Su efecto procinético se produce a altas dosis por antagonismo de los receptores 5-HT3","Es muy eficaz contra vómitos exclusivamente de origen periférico","Puede provocar excitación y ataxia por bloqueo de receptores dopaminérgicos D2","La vía intravenosa está contraindicada"],a:2,
n:"La metoclopramida bloquea los receptores <b>D2</b> (zona gatillo y estómago) y, a dosis altas, los 5-HT3; además es agonista 5-HT4. Su efecto <b>procinético</b> viene del agonismo 5-HT4 y del bloqueo D2; el antagonismo 5-HT3 aporta efecto <b>antiemético</b>. Actúa sobre vómitos centrales y periféricos y se usa mucho en infusión IV continua. El bloqueo D2 central da efectos extrapiramidales: excitación, temblores, ataxia, cambios de conducta."},
{t:2,q:"¿Cuál NO se usa como antiemético?",o:["Metoclopramida","Maropitant","Clorpromazina","Apomorfina"],a:3,
n:"La <b>apomorfina</b> es un agonista dopaminérgico que estimula la zona gatillo: es un <b>emético</b> (se usa para provocar el vómito en el perro tras ingerir un tóxico). Antieméticos: metoclopramida (antagonista D2), maropitant (antagonista NK1, de amplio espectro, también en la cinetosis), fenotiazinas como la clorpromazina (antagonistas D2, H1 y M) y los setrones (5-HT3)."},
{t:2,q:"La angiotensina II. Señala la proposición CORRECTA:",o:["Por unión al receptor AT1 promueve la hipertrofia y proliferación de miocitos","Al unirse al receptor AT1 aumenta la liberación de NO y por tanto su efecto vasodilatador","Al unirse al receptor AT2 provoca vasoconstricción y activación simpática","Por interacción con el receptor AT2 reduce la liberación de aldosterona"],a:0,
n:"Casi todos los efectos «dañinos» de la angiotensina II van por el receptor <b>AT1</b>: vasoconstricción, activación simpática, liberación de aldosterona, retención de Na⁺ y agua, <b>hipertrofia y proliferación</b> de miocitos y fibrosis. El <b>AT2</b> hace lo contrario: vasodilatación (con liberación de NO), efecto antiproliferativo y apoptosis."},
{t:2,q:"Angiotensina II. Señala la opción CORRECTA:",o:["Produce una respuesta hipertensora muy marcada y estimula la liberación adrenal de catecolaminas","Produce una respuesta hipertensora muy marcada y se sintetiza en el aparato yuxtaglomerular","Estimula la liberación adrenal de catecolaminas y produce una respuesta hipotensora muy intensa","Produce una respuesta hipotensora muy intensa y se sintetiza en el aparato yuxtaglomerular"],a:0,
n:"En el test original había <b>varias respuestas correctas</b>; aquí van juntas en una sola opción.<br>✓ <b>Respuesta hipertensora muy marcada</b>: es uno de los vasoconstrictores más potentes (AT1).<br>✓ <b>Estimula la médula adrenal</b> para que libere catecolaminas (además de la aldosterona y la ADH).<br>✗ No es hipotensora.<br>✗ En el aparato yuxtaglomerular se fabrica la <b>renina</b>; la angiotensina II se forma en la sangre y los tejidos (sobre todo en el pulmón) por la ECA."},
{t:2,q:"Angiotensina II. Señala la opción CORRECTA:",o:["Es el principal estímulo de la secreción de aldosterona y es probable que ocasione vasoconstricción renal","Es el principal estímulo de la secreción de aldosterona y es útil en el tratamiento del choque hipovolémico","Es probable que ocasione vasoconstricción renal y la segregan los riñones cuando baja la presión de perfusión","La segregan los riñones cuando baja la presión de perfusión y es útil en el tratamiento del choque hipovolémico"],a:0,
n:"En el test original había <b>varias respuestas correctas</b>; aquí van juntas en una sola opción.<br>✓ Es el <b>principal estímulo de la secreción de aldosterona</b> (junto con la hiperpotasemia).<br>✓ Produce <b>vasoconstricción renal</b> (sobre todo de la arteriola eferente).<br>✗ Lo que segrega el riñón cuando baja la perfusión es la <b>renina</b> (una enzima), no la angiotensina.<br>✗ No se usa para tratar el choque hipovolémico."},
{t:2,q:"Angiotensina II. Señala la FALSA:",o:["Actividad inotrópica potente","Vasoconstricción","Favorece la hipertrofia e hiperplasia cardiacas","Estimula la secreción de vasopresina y ACTH"],a:0,
n:"La angiotensina II tiene un efecto inotropo positivo <b>moderado</b>, no potente; lo que sí es muy potente es su efecto <b>vasoconstrictor</b>. Además estimula la hipertrofia e hiperplasia cardiacas (remodelado), la sed y la secreción de aldosterona, vasopresina (ADH) y ACTH."},
{t:2,q:"Acciones fisiológicas de los péptidos natriuréticos. Señala la proposición INCORRECTA:",o:["Aumentan la filtración glomerular y disminuyen la reabsorción de Na⁺","Aumentan la secreción de renina, endotelina y vasopresina","Los niveles de BNP y ANP sirven para el diagnóstico de la gravedad de la ICC","Aumentan el tono vagal y disminuyen la actividad simpática"],a:1,
n:"Los péptidos natriuréticos (ANP, BNP, CNP) son los «antagonistas» del sistema renina-angiotensina: <b>inhiben</b> la renina, la aldosterona, la endotelina-1 y la vasopresina. Aumentan la filtración glomerular, la natriuresis y la diuresis, dilatan arterias y venas, aumentan el tono vagal y reducen el simpático. El NT-proBNP se usa como marcador de la gravedad de la insuficiencia cardiaca."},
{t:2,q:"¿Cuál de las siguientes NO es causada por la atriopeptina o péptido natriurético auricular (ANP)?",o:["Actividad diurética y natriurética aguda","Relajación de la musculatura lisa vascular","Inhibición de la biosíntesis de aldosterona","Aumento de la liberación de angiotensina"],a:3,
n:"El ANP se libera cuando se distienden las <b>aurículas</b> (exceso de volumen). Produce diuresis y natriuresis, relaja el músculo liso vascular (vasodilatación) e <b>inhibe</b> la renina (y por tanto la formación de angiotensina II), la aldosterona y la ADH."},
{t:2,q:"¿Cuál de las siguientes acciones NO es causada por la atriopeptina?",o:["Son vasodilatadores","Inhiben la secreción de aldosterona","Efecto diurético y natriurético","Producen pérdidas de potasio"],a:3,
n:"El ANP aumenta la excreción de Na⁺ y agua <b>sin apenas pérdida de K⁺</b>, en parte porque inhibe la aldosterona (la que intercambia Na⁺ por K⁺ en el túbulo colector). También es vasodilatador e inhibe la renina y la ADH."},
{t:2,q:"Péptidos natriuréticos. Señala la proposición CORRECTA:",o:["Producen vasodilatación arterial y venosa y tienen actividad antiproliferativa a nivel cardiaco","Aumentan el volumen sanguíneo y el gasto cardiaco","La producción de ANP se estimula ante distensiones de la pared ventricular","Disminuyen el tono vagal y la filtración glomerular"],a:0,
n:"Los péptidos natriuréticos son <b>vasodilatadores mixtos</b> (arteriales y venosos) con efecto antiproliferativo y antifibrótico en el corazón. Reducen la volemia (natriuresis y diuresis) y aumentan el tono vagal y la filtración glomerular. El <b>ANP</b> lo liberan las <b>aurículas</b> al distenderse; el que responde sobre todo a la distensión <b>ventricular</b> es el BNP.<br><i>La opción A estaba incompleta en el original y se ha completado.</i>"},
{t:2,q:"Bradicinina. Señala la opción CORRECTA:",o:["Vasodilatación que no antagoniza la atropina y dolor que es antagonizado por la aspirina","Vasodilatación que no antagoniza la atropina y disminución de la permeabilidad capilar","Dolor que es antagonizado por la aspirina y broncodilatación de las vías aéreas","Disminución de la permeabilidad capilar y broncodilatación de las vías aéreas"],a:0,
n:"En el test original había <b>dos respuestas correctas</b> según la clave de clase; aquí van juntas en una sola opción.<br>✓ <b>Vasodilatación que no antagoniza la atropina</b>: va por receptores B2 y libera NO y PGI2; no actúa sobre receptores muscarínicos.<br>✓ <b>Dolor que antagoniza la aspirina</b>: la bradicinina estimula la síntesis de prostaglandinas, que sensibilizan los nociceptores, y la aspirina reduce esa parte del dolor.<br>✗ <b>Aumenta</b> la permeabilidad capilar (edema) y produce <b>broncoconstricción</b>.<br>La degrada la ECA: por eso los IECA pueden dar tos."},
{t:2,q:"Eicosanoides. Señala la proposición CORRECTA:",o:["Los leucotrienos A4 y B4 constituyen la sustancia de reacción lenta de la anafilaxia","Los análogos de PG son útiles para disminuir la presión intraocular","La PGE2 fomenta la secreción ácida gástrica","Los análogos de PGF2α se utilizan para tratar la coagulación intravascular diseminada"],a:1,
n:"Los análogos de PGF2α (<b>latanoprost</b>, travoprost) aumentan la salida del humor acuoso por la vía uveoescleral y <b>bajan la presión intraocular</b> (glaucoma). La sustancia de reacción lenta de la anafilaxia son los cisteinil-leucotrienos <b>C4, D4 y E4</b>. La PGE2 <b>inhibe</b> la secreción ácida y protege la mucosa (misoprostol). Los eicosanoides no se usan en la CID."},
{t:2,q:"Acción que NO corresponde a la PGF2α:",o:["Broncoconstricción","Disminución del peristaltismo por relajación del músculo liso","Oxitócica y luteolítica","Disminuye la diuresis"],a:1,
n:"La PGF2α <b>contrae</b> el músculo liso: bronquios (broncoconstricción), útero (acción oxitócica) e intestino (<b>aumenta</b> el peristaltismo; por eso la diarrea y los cólicos son efectos adversos del dinoprost). Además es <b>luteolítica</b>: base de su uso para sincronizar celos, inducir partos y abortos y tratar la piómetra."},
{t:2,q:"Acciones de la PGF2α. Señala la opción CORRECTA:",o:["Produce broncoconstricción y tiene acción oxitócica y luteolítica","Broncoconstricción y menos peristaltismo al relajar el músculo liso","Acción oxitócica y luteolítica y más absorción de agua, Na⁺ y glucosa","Menos peristaltismo y más absorción intestinal de agua, Na⁺ y glucosa"],a:0,
n:"En el test original había <b>varias respuestas correctas</b>; aquí van juntas en una sola opción.<br>✓ <b>Broncoconstricción</b>: contrae el músculo liso bronquial.<br>✓ <b>Oxitócica</b> (contrae el útero) y <b>luteolítica</b> (destruye el cuerpo lúteo): dinoprost y cloprostenol.<br>✗ En el intestino <b>aumenta</b> el peristaltismo (contrae, no relaja).<br>✗ Las prostaglandinas favorecen la <b>secreción</b> intestinal de agua y electrolitos (diarrea), no su absorción."},
{t:2,q:"Tromboxano A2. Señala la opción CORRECTA:",o:["Es un potente vasoconstrictor y su síntesis se inhibe por déficit de vitamina E","Es un potente vasoconstrictor e inhibe la agregación de las plaquetas","Inhibe la formación de trombos y su síntesis se inhibe por déficit de vitamina E","Inhibe la agregación de las plaquetas y la formación de trombos"],a:0,d:true,
n:"En el test original había <b>dos respuestas correctas</b> según la clave de clase; aquí van juntas en una sola opción.<br>✓ <b>Potente vasoconstrictor</b> y proagregante: lo fabrican las plaquetas por la COX-1.<br>✓ <b>Su síntesis se inhibe por déficit de vitamina E</b>: es la segunda que marca la clave (pregunta de 2 respuestas). Ojo: en la bibliografía general el déficit de vitamina E suele asociarse a más TXA2, no a menos; quédate con lo que explique tu profesora.<br>✗ No inhibe la agregación ni la formación de trombos: las favorece. Su contrapeso es la <b>PGI2</b> del endotelio."},
{t:2,q:"Los leucotrienos NO ocasionan:",o:["Vasodilatación","Aumento de la permeabilidad vascular","Efecto quimiotáctico sobre linfocitos","Efecto quimiotáctico sobre neutrófilos"],a:2,d:true,
n:"La clave de clase marca la <b>quimiotaxis de linfocitos</b>: según tus apuntes de eicosanoides, el LTB4 es quimiotáctico de <b>macrófagos y neutrófilos</b> (la clave anota también eosinófilos, cuya quimiotaxis regulan las lipoxinas). Los cisteinil-leucotrienos (LTC4, LTD4, LTE4) producen broncoconstricción y <b>aumentan la permeabilidad vascular</b>.<br>Ojo: la vasodilatación también es discutible, porque en la mayoría de los vasos (sobre todo los coronarios) los leucotrienos producen vasoconstricción; otra clave marcó la de neutrófilos, con dudas."},
{t:2,q:"Indicaciones en veterinaria del cloprostenol (análogo de PGF2α). Señala la INCORRECTA:",o:["Cuerpo lúteo persistente","Para provocar el aborto","Sincronización del celo","Disminución de la producción seminal en el verraco"],a:3,
n:"El cloprostenol es <b>luteolítico</b>: se usa en el cuerpo lúteo persistente, la sincronización de celos, la inducción del parto (cerda) y del aborto, y la piómetra. En el verraco <b>aumenta</b> la libido y la producción seminal, no la disminuye."},
{t:2,q:"Efectos de los prostanoides. Señala la proposición INCORRECTA:",o:["PGF2α y TXA2 producen broncoconstricción","La PGE2 a nivel digestivo posee efecto citoprotector, disminuye la producción ácida y acelera el tránsito","El TXA2 posee efecto vasodilatador","PGI2 y PGE2 a nivel cardiovascular poseen efecto vasodilatador e hipotensor y producen taquicardia"],a:2,
n:"El <b>TXA2 es vasoconstrictor</b> y proagregante. PGI2 y PGE2 son vasodilatadoras e hipotensoras (con taquicardia refleja). La PGE2 protege la mucosa gástrica (↓ ácido, ↑ moco y bicarbonato) y acelera el tránsito intestinal. PGF2α y TXA2 contraen los bronquios."},
{t:2,q:"¿Cuál NO es un efecto farmacológico de la PGE2?",o:["Vasodilatación y aumento de la permeabilidad capilar","Efecto antiagregante plaquetario","Aumento del flujo renal","Bradicardia"],a:3,
n:"La PGE2 es vasodilatadora e hipotensora: la caída de la presión provoca <b>taquicardia refleja</b>, no bradicardia. También aumenta la permeabilidad capilar (inflamación) y el flujo sanguíneo renal (por eso los AINEs dañan el riñón cuando hay hipovolemia), y a concentraciones altas inhibe la agregación plaquetaria."},
{t:3,q:"Señala la FALSA sobre los AINEs:",o:["Dipirona y paracetamol tienen débiles efectos antiinflamatorios","Tienen una acción antiálgica moderada, no útil en el dolor por estimulación mecánica o eléctrica","La tepoxalina tiene mayor actividad antiinflamatoria porque inhibe también la síntesis de leucotrienos","Su actividad antiinflamatoria se debe a la inhibición de la COX-3"],a:3,
n:"La actividad <b>antiinflamatoria</b> se debe a la inhibición de la <b>COX-2</b> (inducible en el foco inflamatorio). La COX-3 (variante central de la COX-1) se relaciona con los efectos <b>antipirético y analgésico</b>; por eso el paracetamol y la dipirona (metamizol) son buenos analgésicos y antipiréticos pero antiinflamatorios débiles. La tepoxalina es un inhibidor dual COX y 5-LOX.<br>Además, según tus apuntes (actualización 2025/2026), la COX-3 está descartada en humanos: es una proteína truncada sin actividad."},
{t:3,q:"Farmacocinética de los AINEs. Señala la opción CORRECTA:",o:["Su absorción oral es rápida y completa y pueden formar metabolitos con actividad antiinflamatoria","Su absorción oral es rápida y completa y presentan volúmenes de distribución elevados","Pueden formar metabolitos con actividad antiinflamatoria y se unen poco a proteínas plasmáticas","Se unen poco a proteínas plasmáticas y su eliminación es fundamentalmente biliar"],a:0,
n:"En el test original había <b>varias respuestas correctas</b>; aquí van juntas en una sola opción.<br>✓ <b>Absorción oral rápida y completa</b> (en monogástricos; en rumiantes y en caballos con comida puede ser más lenta).<br>✓ Algunos tienen <b>metabolitos activos</b>: la fenilbutazona da oxifenbutazona, la nabumetona es un profármaco y la aspirina pasa a salicilato.<br>✗ Son ácidos débiles con <b>alta unión a proteínas</b> → <b>Vd bajo</b>.<br>✗ Se eliminan sobre todo por la <b>orina</b>, no por la bilis."},
{t:3,q:"AINEs. Señala la proposición FALSA:",o:["Metamizol y paracetamol son buenos analgésicos con escasa actividad antiinflamatoria","El diflunisal es un salicilato con mínimo efecto antipirético","En el ketorolaco predomina la acción antiinflamatoria sobre la analgésica","Los oxicams son potentes antiinflamatorios"],a:2,
n:"En el <b>ketorolaco predomina la acción analgésica</b>: es uno de los AINEs más analgésicos (dolor posoperatorio) y su efecto antiinflamatorio es moderado. Los oxicams (piroxicam, meloxicam) son potentes antiinflamatorios; el diflunisal apenas es antipirético; metamizol y paracetamol son analgésicos y antipiréticos con escasa acción antiinflamatoria."},
{t:3,q:"AINEs. ¿Cuál de las siguientes proposiciones es FALSA?",o:["No desarrollan tolerancia","Son más antiálgicos que analgésicos","Su asociación está indicada porque se establece una sinergia aditiva","No son efectivos en la hipertermia por ejercicio excesivo"],a:2,
n:"<b>No se deben asociar dos AINEs</b>: comparten mecanismo, así que no se gana eficacia y se suman los efectos adversos (úlceras, daño renal). Al cambiar de uno a otro se deja un periodo de lavado. Los AINEs no dan tolerancia, alivian sobre todo el dolor de origen inflamatorio («antiálgicos») y no sirven en la hipertermia por ejercicio o golpe de calor."},
{t:3,q:"AINEs. Señala la FALSA:",o:["Su uso crónico provoca tolerancia","Tienen actividad antiagregante plaquetaria, irreversible en el caso del AAS","La actividad analgésica se debe a la inhibición de la COX","Reducen la temperatura anormalmente elevada, pero no producen hipotermia"],a:0,
n:"Los AINEs <b>no producen tolerancia</b> ni dependencia (a diferencia de los opioides). Inhiben la agregación plaquetaria: de forma <b>irreversible</b> la aspirina (acetila la COX-1) y reversible el resto. Su analgesia se debe a la inhibición de la síntesis de prostaglandinas, y bajan la fiebre sin producir hipotermia."},
{t:3,q:"AINEs. Señala la FALSA:",o:["Tienen actividad ulcerógena por inhibición de las PGE","Provocan alcalosis metabólica","Disminuyen la velocidad de filtración glomerular y el flujo sanguíneo renal","Pueden provocar diátesis hemorrágica"],a:1,
n:"Los AINEs (sobre todo los salicilatos en sobredosis) producen <b>acidosis</b>: al principio alcalosis respiratoria por hiperventilación y después <b>acidosis mixta respiratoria y metabólica</b>. Son ulcerógenos (↓ PGE2 protectora), reducen el flujo renal y la filtración glomerular y pueden causar diátesis hemorrágica (↓ TXA2 plaquetario)."},
{t:3,q:"AINEs y ciclooxigenasas. Señala la CORRECTA:",o:["La COX-1 es responsable de la homeostasis a nivel gástrico y renal","La enzima COX-1 es inducible","Sus efectos adversos se deben sobre todo a la inhibición de la COX-2","Se acumulan en el foco inflamatorio por la alcalosis local"],a:0,
n:"En el test original era una sola pregunta con 8 afirmaciones (4 falsas); aquí está partida en dos preguntas para no perder ninguna.<br>La <b>COX-1 es constitutiva</b>: fabrica las prostaglandinas que protegen la mucosa gástrica, mantienen el flujo renal y permiten la agregación plaquetaria; inhibirla causa la mayoría de los <b>efectos adversos</b>. La <b>COX-2 es inducible</b> en la inflamación: inhibirla da los efectos terapéuticos. Los AINEs, ácidos débiles muy unidos a proteínas, se acumulan en el foco inflamatorio por el <b>pH ácido</b> y la mayor permeabilidad vascular."},
{t:3,q:"AINEs. Señala la FALSA:",o:["Sus efectos farmacológicos se deben a la inhibición de la COX-2","La inhibición de la COX-3 está relacionada con el efecto analgésico","La COX-2 es la responsable de la homeostasis a nivel gástrico y renal","Las vidas medias presentan grandes variaciones intra e interespecíficas"],a:2,d:true,
n:"En el test original era una sola pregunta con 8 afirmaciones (4 falsas); aquí está partida en dos preguntas para no perder ninguna.<br>La homeostasis gástrica y renal depende sobre todo de la <b>COX-1</b> (constitutiva). La COX-2 es inducible y su inhibición explica los efectos antiinflamatorios; la COX-3 (central) se relaciona con la analgesia y la antipiresis. La vida media de los AINEs varía muchísimo entre especies e individuos (aspirina: gato ≈ 38 h, perro ≈ 8 h, caballo ≈ 1 h).<br><b>Ojo, según tus apuntes (actualización 2025/2026):</b> la profesora explica que en humanos la COX-3 no existe como enzima funcional y que se descarta que el paracetamol actúe por ella. Esta pregunta es de exámenes anteriores, que daban la COX-3 por buena; si este año aparece, la afirmación sobre la COX-3 también podría considerarse falsa."},
{t:3,q:"Efectos farmacológicos de los AINEs. Señala la proposición INCORRECTA:",o:["No son efectivos en la hipertermia debida a ejercicio intenso","Tienen actividad vasodilatadora a nivel periférico","La actividad antiinflamatoria es debida a la inhibición de la COX-3","Los fenamatos tienen acción directa contra las PGs ya presentes en los tejidos"],a:2,
n:"La acción <b>antiinflamatoria</b> depende de la inhibición de la <b>COX-2</b>; la COX-3 se relaciona con la analgesia y la antipiresis. Cuando bajan la fiebre lo hacen favoreciendo la pérdida de calor por <b>vasodilatación periférica</b> y sudoración. Los fenamatos (ácidos meclofenámico y tolfenámico) además antagonizan las PGs ya formadas.<br>Además, según tus apuntes (actualización 2025/2026), la COX-3 está descartada en humanos: es una proteína truncada sin actividad."},
{t:3,q:"Paracetamol:",o:["Buen antiinflamatorio","Buen analgésico y antipirético","Agente ulcerógeno","Buen uricosúrico"],a:1,
n:"El paracetamol (acetaminofén) es <b>buen analgésico y antipirético</b> (actúa sobre todo a nivel central) pero <b>antiinflamatorio muy débil</b>, porque en el foco inflamatorio, con muchos peróxidos, apenas inhibe la COX. Casi no es ulcerógeno. Está <b>contraindicado en el gato</b>, que no puede glucuronidarlo (metahemoglobinemia y daño hepático)."},
{t:3,q:"Flunixin meglumina. Señala la CORRECTA:",o:["Es útil en el dolor visceral del cólico y en el dolor musculoesquelético","Es menos analgésico y antiinflamatorio que la fenilbutazona","Está contraindicado en el caballo","Carece de utilidad en la endotoxemia"],a:0,
n:"En el test original había dos respuestas correctas («útil en espasmos viscerales» y «se usa en el dolor musculoesquelético»); aquí van juntas en una sola opción.<br>El flunixin es un AINE muy usado en <b>grandes animales</b>: es un analgésico potente en el <b>dolor visceral</b> (cólico del caballo) y también se usa en el musculoesquelético; a dosis bajas reduce los efectos de la <b>endotoxemia</b>. En el dolor visceral es más eficaz que la fenilbutazona. Ojo: puede enmascarar un cólico quirúrgico."},
{t:3,q:"Señala la proposición INCORRECTA sobre los modificadores de la enfermedad en la artritis reumatoide:",o:["Infliximab es un inhibidor de la síntesis de IL-1","Rituximab induce la apoptosis de linfocitos B, sobre todo en sangre periférica","Abatacept es una proteína de fusión que modula la activación de las células T","Leflunomida puede retrasar la progresión radiológica de la lesión articular"],a:0,
n:"El <b>infliximab</b> es un anticuerpo monoclonal quimérico <b>anti-TNFα</b> (como el adalimumab; el etanercept es un receptor soluble del TNF). Contra la IL-1 actúa la anakinra.<br>• Rituximab: anti-CD20, elimina linfocitos B.<br>• Abatacept: CTLA4-Ig, bloquea la coestimulación de los linfocitos T.<br>• Leflunomida: inhibe la síntesis de pirimidinas en los linfocitos y frena el daño articular."},
{t:3,q:"¿Cuáles son modificadores NO biológicos de la artritis reumatoide?",o:["Etanercept y rituximab","Leflunomida y sulfasalazina","Leflunomida y rituximab","Sulfasalazina y etanercept"],a:1,
n:"En el test original había <b>varias respuestas correctas</b>; aquí van juntas en una sola opción.<br>✓ <b>Leflunomida</b> y <b>sulfasalazina</b> son FAME <b>sintéticos</b> (no biológicos), igual que el metotrexato y la hidroxicloroquina (convencionales) y los inhibidores JAK como el tofacitinib (dirigidos).<br>✗ <b>Etanercept</b> (receptor soluble del TNF) y <b>rituximab</b> (anti-CD20) son <b>biológicos</b>: proteínas obtenidas por biotecnología."},
{t:3,q:"Metotrexato. Señala la respuesta INCORRECTA:",o:["Es un antimetabolito que inhibe la dihidropteroato sintetasa","Inhibe parcialmente el sistema inmunitario y reduce la inflamación articular de origen autoinmune","Puede reducir la formación de anticuerpos neutralizantes en los tratamientos con fármacos biológicos","Puede producir toxicidad a nivel pulmonar"],a:0,
n:"El metotrexato es un análogo del ácido fólico que inhibe la <b>dihidrofolato reductasa</b> (DHFR); la dihidropteroato sintetasa es la diana de las <b>sulfamidas</b>. A dosis bajas es el FAME de referencia en la artritis reumatoide (inmunosupresor y antiinflamatorio) y, asociado a biológicos como el infliximab, reduce los anticuerpos contra ellos. Toxicidad: médula ósea, hígado, <b>pulmón</b> (neumonitis) y mucosas.<br><i>Pregunta incompleta en el original; se ha completado.</i>"},
{t:3,q:"Anticuerpos monoclonales (fármacos terminados en -mab). Señala la proposición CORRECTA:",o:["Son útiles para reducir la inflamación y frenar la progresión de la enfermedad","Solo controlan el dolor, sin modificar la evolución de la enfermedad","Se pueden utilizar por vía oral","Solo se utilizan en medicina humana"],a:0,d:true,
n:"En la artritis reumatoide los anticuerpos monoclonales (infliximab y adalimumab, anti-TNF; rituximab, anti-CD20; tocilizumab, anti-IL-6) son <b>FAME biológicos</b>: reducen la inflamación y frenan el daño articular. Son proteínas: se dan por vía <b>parenteral</b> (IV o SC), nunca oral. En veterinaria existen, por ejemplo, el bedinvetmab (perro) y el frunevetmab (gato), anti-NGF para el <b>dolor</b> de la artrosis; si la pregunta se refería a ellos, la respuesta podría cambiar.<br><i>Pregunta incompleta en el original; se ha completado.</i>"},
{t:4,q:"Sobre los siguientes enunciados, indica la CORRECTA:",o:["Uno de los mecanismos de acción indirecta de los glucocorticoides es la activación del factor nuclear kappa B y de la proteína activadora 1","La interacción del glucocorticoide con receptores de membrana produce efectos genómicos rápidos","La isoforma 2 de la 11β-HSD inactiva el cortisol y la corticosterona en riñón, colon y glándulas salivares, mientras que la isoforma 1 regenera dichas hormonas en el resto de tejidos","El receptor glucocorticoide es inactivo y se encuentra en la membrana de la célula, formando complejos con otras proteínas"],a:2,
n:"La <b>11β-HSD2</b> (tejidos diana de la aldosterona: riñón, colon, glándulas salivares) inactiva el cortisol a cortisona y así protege al receptor mineralocorticoide; la <b>11β-HSD1</b> (hígado, tejido adiposo, cerebro, pulmón) lo reactiva. Los GC <b>inhiben</b> NF-κB y AP-1 (transrepresión). Los receptores de membrana dan efectos rápidos <b>no genómicos</b>. El receptor GC inactivo está en el <b>citoplasma</b>, unido a HSP90."},
{t:4,q:"NO es un efecto de los glucocorticoides:",o:["Inhiben la utilización periférica de la glucosa","Estimulan la síntesis hepática de enzimas que intervienen en la gluconeogénesis","Poseen poca o nula actividad lipolítica","Producen aumento de la absorción intestinal del calcio","Producen movilización de aminoácidos y proteínas"],a:3,
n:"Los GC <b>disminuyen la absorción intestinal de calcio</b> (antagonizan la vitamina D) y aumentan su excreción renal; por eso a largo plazo producen osteoporosis e hiperparatiroidismo secundario. En el metabolismo son hiperglucemiantes: inhiben la captación periférica de glucosa, inducen las enzimas de la gluconeogénesis y movilizan aminoácidos del músculo (catabolismo proteico). Su acción lipolítica directa es escasa o nula (solo potencian la de otras hormonas), así que esa opción sí es un efecto."},
{t:4,q:"Glucocorticoides. Señala la CORRECTA:",o:["Sufren efecto de primer paso","Atraviesan la BHE, por lo que pueden dar efectos secundarios a nivel central","Se eliminan exclusivamente por vía hepática","Apenas se unen a proteínas plasmáticas"],a:1,d:true,
n:"Lo seguro: <b>atraviesan la BHE</b> (y la placenta), por eso dan efectos centrales (euforia, cambios de conducta, polifagia). Se unen mucho a proteínas (transcortina y albúmina) y se eliminan sobre todo por la <b>orina</b>, no solo por el hígado.<br>Discutible: por vía oral se absorben bien y, en general, sin un primer paso importante; la excepción es la prednisona, que necesita activarse en el hígado (a prednisolona). Si tu profesor daba también por buena la del primer paso, la respuesta completa sería «sufren efecto de primer paso y atraviesan la BHE»."},
{t:4,q:"Efectos de los glucocorticoides. Señala la INCORRECTA:",o:["A nivel hepático estimulan la glucogénesis y la gluconeogénesis","Poseen escasa acción lipolítica, pero su acción permisiva sobre otras hormonas produce movilización de las grasas","Disminuyen la filtración glomerular","Interfieren en la absorción de calcio a nivel intestinal"],a:2,
n:"Los GC <b>aumentan</b> la filtración glomerular y el flujo renal y favorecen la excreción de agua libre (junto con la inhibición de la ADH, explica la poliuria). Lo demás es cierto: en el hígado estimulan la gluconeogénesis y el depósito de glucógeno; tienen efecto lipolítico permisivo (potencian a catecolaminas y GH) y reducen la absorción intestinal de calcio."},
{t:4,q:"¿Cuál de las siguientes NO es una reacción adversa de los glucocorticoides?",o:["Pueden producir hepatomegalia en perros","Pueden ocasionar diátesis hemorrágica","Pueden provocar cataratas subcapsulares y úlceras corneales","Los tratamientos prolongados ocasionan degeneración y atrofia muscular"],a:1,
n:"Los GC no causan diátesis hemorrágica: aumentan las plaquetas y favorecen la <b>hipercoagulabilidad</b> (riesgo de tromboembolismo). La diátesis hemorrágica es típica de los AINEs. Sí son reacciones adversas de los GC: <b>hepatomegalia</b> (hepatopatía esteroidea del perro, con ↑ fosfatasa alcalina), cataratas, empeoramiento de úlceras corneales y atrofia muscular."},
{t:4,q:"Inhibidores de los glucocorticoides. Señala la proposición CORRECTA:",o:["La metopirona solo se utiliza como tratamiento médico tras la cirugía de un carcinoma adrenal","El uso del mitotano está muy limitado por su toxicidad gastrointestinal y neurológica","La aminoglutetimida es útil en el hipercortisolismo, pero provoca hipertiroidismo","El trilostano es un fármaco poco utilizado en medicina veterinaria"],a:1,
n:"El <b>mitotano</b> (o,p'-DDD) destruye la corteza adrenal; sus efectos adversos digestivos (anorexia, vómitos, diarrea) y neurológicos (letargia, ataxia), además del riesgo de crisis addisoniana, limitan su uso. El <b>trilostano</b> (inhibe la 3β-HSD) es hoy el tratamiento de elección del Cushing canino. La metopirona (inhibe la 11β-hidroxilasa) se usa sobre todo en el gato. La aminoglutetimida puede producir <b>hipotiroidismo</b>."},
{t:4,q:"Glucocorticoides. Señala la FALSA:",o:["Aumentan la glucemia y el glucógeno hepático","Aumentan la excreción renal de calcio","Inhiben la actividad paratiroidea","Inducen catabolismo proteico"],a:2,
n:"Al reducir la absorción intestinal de calcio y aumentar su excreción renal, los GC tienden a bajar el calcio y <b>estimulan</b> la paratiroides (hiperparatiroidismo secundario), lo que contribuye a la osteoporosis. Además son hiperglucemiantes (aumentan la glucemia y el glucógeno hepático) y catabólicos proteicos."},
{t:4,q:"Glucocorticoides. Señala la FALSA:",o:["Atrofia cutánea","Osteoporosis","Aumento de la presión intraocular","Actividad hipolipemiante"],a:3,
n:"Los GC producen <b>hiperlipidemia</b> (aumento de colesterol y triglicéridos) y redistribución de la grasa, no actividad hipolipemiante. La atrofia de la piel, la osteoporosis y el aumento de la presión intraocular (glaucoma), sobre todo con colirios, sí son efectos adversos."},
{t:4,q:"Efectos antiinflamatorios de los glucocorticoides. Señala la FALSA:",o:["Afectan a los procesos de reparación tisular, puesto que impiden la respuesta celular","Disminuyen el tono capilar","Aumentan el metabolismo de la histamina e inhiben su síntesis","Estabilizan las membranas lisosomales"],a:1,
n:"Los GC <b>aumentan el tono capilar</b> (potencian la vasoconstricción por catecolaminas) y reducen la permeabilidad: así disminuyen el edema y el exudado. Además estabilizan las membranas lisosomales, reducen la histamina disponible y frenan la migración de leucocitos y la proliferación de fibroblastos; por eso <b>retrasan la cicatrización</b>."},
{t:4,q:"Glucocorticoides. Señala la opción CORRECTA:",o:["Retienen sodio y agua en el túbulo con pérdida de potasio, y tienen un efecto negativo sobre el sistema inmunitario","Retienen sodio y agua en el túbulo renal con pérdida de potasio, y en el SNC disminuyen la actividad motora","Tienen un efecto negativo sobre el sistema inmunitario y son hipotensores al favorecer la reabsorción tubular de Na⁺","En el SNC disminuyen la actividad motora y son hipotensores al favorecer la reabsorción tubular de Na⁺"],a:0,
n:"En el test original había <b>varias respuestas correctas</b>; aquí van juntas en una sola opción.<br>✓ Por su efecto mineralocorticoide (marcado en hidrocortisona y prednisolona, casi nulo en dexametasona) <b>retienen Na⁺ y agua y eliminan K⁺</b>.<br>✓ Tienen un <b>efecto negativo sobre el sistema inmunitario</b>: son inmunosupresores.<br>✗ En el SNC producen euforia, inquietud y <b>más</b> actividad, no menos.<br>✗ Al retener Na⁺ y agua son <b>hipertensores</b>, no hipotensores."},
{t:4,q:"Los glucocorticoides están recomendados en:",o:["Dermatomicosis infecciosas, asociados a quimioterápicos","Úlceras corneales","Procesos inflamatorios agudos y crónicos","Diabetes mellitus"],a:2,
n:"Los GC están indicados en <b>procesos inflamatorios agudos y crónicos</b>, alergias, enfermedades inmunomediadas, shock y algunas neoplasias (linfomas). Están <b>contraindicados</b> en las micosis, las úlceras corneales (retrasan la cicatrización y favorecen la perforación) y la diabetes mellitus (son hiperglucemiantes)."},
{t:4,q:"Los glucocorticoides NO producen:",o:["Catabolismo proteico","Glucogenólisis","Gluconeogénesis","Acción permisiva lipolítica sobre las catecolaminas"],a:1,
n:"En el hígado los GC estimulan la gluconeogénesis y el <b>depósito de glucógeno</b> (glucogénesis), no su degradación (la glucogenólisis es propia del glucagón y la adrenalina). Los aminoácidos para la gluconeogénesis salen del <b>catabolismo proteico</b> del músculo. Su efecto lipolítico es sobre todo permisivo (potencian a las catecolaminas)."},
{t:4,q:"Efectos de los glucocorticoides. Señala la FALSA:",o:["Inhiben la utilización periférica de glucosa","Intervienen en la absorción de calcio a nivel gastrointestinal","Son hipotensores","Aumentan el catabolismo de la matriz ósea e inhiben la actividad osteoblástica"],a:2,
n:"Los GC son <b>hipertensores</b>: retienen Na⁺ y agua (↑ volemia) y potencian el efecto vasoconstrictor de las catecolaminas. Además inhiben la utilización periférica de la glucosa, reducen la absorción intestinal de calcio y, en el hueso, inhiben los osteoblastos y aumentan la resorción → osteoporosis."},
{t:4,q:"Efectos de los glucocorticoides. Señala la respuesta INCORRECTA:",o:["Favorecen la movilización de proteínas y aminoácidos","Fomentan la utilización periférica de la glucosa","Intervienen en la absorción del calcio a nivel gastrointestinal","Se caracterizan por ser hipertensores e inmunosupresores"],a:1,
n:"Los GC <b>inhiben</b> la utilización periférica de la glucosa (son hiperglucemiantes y pueden desencadenar una diabetes). Sí movilizan proteínas y aminoácidos (catabolismo), reducen la absorción intestinal de calcio y son hipertensores e inmunosupresores.<br><i>Pregunta incompleta en el original; se ha completado.</i>"},
{t:4,q:"¿Cuál NO es un efecto adverso de los glucocorticoides?",o:["Provocan hipertensión","Retraso en la cicatrización","Aumento de la presión intraocular","Pueden aumentar de manera temporal la secreción láctea"],a:3,
n:"En las vacas lecheras los GC (dexametasona) producen una <b>disminución temporal de la producción de leche</b>, no un aumento. La hipertensión (retención de Na⁺ y agua), el retraso de la cicatrización y el aumento de la presión intraocular sí son efectos adversos."},
{t:4,q:"Farmacocinética de los glucocorticoides. Señala la INCORRECTA:",o:["Se unen mucho a proteínas plasmáticas (transcortina y albúmina)","Se eliminan fundamentalmente en heces","Se biotransforman en todos los tejidos, más a nivel hepático","Atraviesan la BHE y la barrera fetoplacentaria"],a:1,
n:"Los GC se eliminan <b>sobre todo por la orina</b> (como metabolitos conjugados); una parte menor va a heces y leche. Se unen mucho a la transcortina y la albúmina, se metabolizan en el hígado y en otros tejidos (riñón) y atraviesan la BHE y la placenta (al final de la gestación pueden desencadenar el parto en rumiantes)."},
{t:4,q:"Glucocorticoides. Señala la CORRECTA:",o:["Su actividad antipirética es muy útil en terapéutica","No intervienen en la absorción del calcio intestinal","Facilitan la síntesis de adrenalina en la médula adrenal","No son inmunosupresores"],a:2,
n:"El cortisol que llega a la médula adrenal induce la <b>feniletanolamina-N-metiltransferasa</b> (PNMT), la enzima que convierte la noradrenalina en <b>adrenalina</b>. Los GC sí son antipiréticos, pero no se usan para eso (enmascaran infecciones); reducen la absorción intestinal de calcio y son inmunosupresores."},
{t:4,q:"Corticoides. Señala la FALSA:",o:["Apenas tienen actividad lipolítica directa","Producen catabolismo de proteínas y movilización de aminoácidos en los tratamientos crónicos","Indirectamente inhiben la lipasa","Dosis altas y prolongadas producen una redistribución peculiar de la grasa en cuello, hombros y mejillas"],a:2,
n:"Los GC apenas son lipolíticos por sí mismos, pero <b>indirectamente favorecen la lipólisis</b>: tienen un efecto permisivo que potencia la activación de la lipasa sensible a hormonas por catecolaminas y GH. A dosis altas mantenidas redistribuyen la grasa (cuello, tronco, abdomen: el «abdomen péndulo» del perro) y producen catabolismo proteico."},
{t:4,q:"Efectos cardiovasculares de los corticoides:",o:["Producen hipertensión","Disminuyen la reactividad a las catecolaminas","Inhiben la vasoconstricción","Disminuyen la volemia porque retienen agua"],a:0,
n:"Los corticoides son <b>hipertensores</b>: retienen Na⁺ y agua (↑ volemia) y <b>aumentan la reactividad vascular</b> a las catecolaminas (efecto permisivo). Por eso en el hipoadrenocorticismo aparece una hipotensión que responde mal a los vasopresores."},
{t:4,q:"Glucocorticoides. Señala la CORRECTA:",o:["Tienen actividad antipirética muy utilizada en terapéutica","A dosis bajas provocan atrofia muscular","Sus efectos metabólicos inhiben la utilización periférica de glucosa","Uno de sus efectos gastrointestinales es el aumento de la secreción de PG"],a:2,
n:"Los GC son <b>hiperglucemiantes</b>: inhiben la captación y la utilización periférica de la glucosa (músculo, tejido adiposo) y estimulan la gluconeogénesis. La atrofia muscular aparece con dosis altas o tratamientos largos. En el estómago <b>reducen</b> las prostaglandinas protectoras (inhiben la fosfolipasa A2 y la COX-2), lo que favorece las úlceras."},
{t:4,q:"Efectos de los glucocorticoides sobre la sangre y el sistema cardiovascular. Señala la proposición INCORRECTA:",o:["Reducen la actividad de los macrófagos y la liberación de radicales libres","Inhiben la secreción de proteínas del complemento y de eicosanoides","Poseen acción lítica sobre ciertas células neoplásicas en leucemias agudas","Aumentan la formación de edema y el depósito de fibrina"],a:3,
n:"Los GC <b>reducen</b> el edema y el depósito de fibrina: disminuyen la permeabilidad capilar y la exudación. También frenan a los macrófagos (menos radicales libres y citocinas), inhiben el complemento y los eicosanoides y tienen acción <b>linfolítica</b>; por eso forman parte de la quimioterapia de linfomas y leucemias linfoides."},
{t:4,q:"Tras el diagnóstico de un síndrome de Addison en un perro, para su tratamiento se recomienda:",o:["Tratar con glucocorticoides hasta conseguir su completa curación","No usar nunca dexametasona o prednisolona por el alto riesgo de síndrome de Cushing iatrogénico","Establecer un tratamiento monitorizado según la respuesta con glucocorticoides","Administrar pentobarbital, pues es el mejor fármaco con actividad anti-Addison"],a:2,
n:"El hipoadrenocorticismo <b>no se cura</b>: el tratamiento es de por vida y se ajusta según la respuesta clínica y los electrolitos. Se dan <b>glucocorticoides</b> a dosis fisiológicas (prednisolona) y, si falta la aldosterona, <b>mineralocorticoides</b> (DOCP inyectable o fludrocortisona oral). En la crisis addisoniana: fluidos y GC por vía IV (hidrocortisona o dexametasona)."},
{t:4,q:"De los siguientes fármacos, ¿cuál es una opción para el tratamiento del hipercortisolismo o síndrome de Cushing de origen hipofisario?",o:["Selegilina","Metopirona","Mifepristona","Aminoglutetimida"],a:0,
n:"La <b>selegilina</b> (L-deprenilo, inhibidor de la MAO-B) aumenta el tono dopaminérgico, que frena la secreción de ACTH en la hipófisis: actúa sobre el <b>origen hipofisario</b> (aunque es poco eficaz). La metopirona y la aminoglutetimida actúan en la <b>adrenal</b> bloqueando la síntesis de cortisol, y la mifepristona bloquea el receptor GC. El tratamiento de elección sigue siendo el trilostano."},
{t:4,q:"Señala la proposición INCORRECTA sobre la ACTH:",o:["Es útil en la cetosis bovina","Puede utilizarse para el diagnóstico diferencial de la insuficiencia adrenal primaria y secundaria","Se administra por vía oral, existiendo formulaciones de liberación prolongada","Estimula la síntesis y liberación de glucocorticoides en la corteza adrenal"],a:2,
n:"La ACTH (corticotropina, tetracosactida) es un <b>péptido</b>: se destruiría en el tubo digestivo, así que se administra por vía <b>parenteral</b> (IV o IM); las formas de liberación prolongada son inyectables (gel o depot). Estimula la producción de cortisol: se usa en la <b>prueba de estimulación con ACTH</b> (Addison, Cushing) y en la cetosis bovina.<br><i>Pregunta incompleta en el original: la opción D se ha completado.</i>"},
{t:4,q:"Mineralocorticoides. Señala la proposición INCORRECTA:",o:["Los efectos genómicos de la aldosterona producen un aumento precoz de canales de sodio en la membrana de las células de los túbulos colectores","Los efectos no genómicos regulan el aumento de moléculas de ATPasa Na⁺/K⁺ en la membrana basolateral","Las reacciones adversas que pueden provocar son alcalosis hipopotasémica con parálisis musculares y alteraciones cardiacas","La aldosterona no se usa clínicamente; se usan DOCA por vía parenteral y fludrocortisona"],a:1,
n:"El aumento del número de bombas <b>Na⁺/K⁺-ATPasa</b> requiere síntesis de proteínas: es un efecto <b>genómico</b> tardío (horas). Los efectos genómicos precoces aumentan la actividad de los canales de Na⁺ (ENaC) de la membrana apical. Los efectos <b>no genómicos</b> son rápidos (segundos o minutos) y van por receptores de membrana. Un exceso de mineralocorticoides produce retención de Na⁺, hipopotasemia y alcalosis."},
{t:5,q:"Inhibidores de la enzima conversora de angiotensina (IECA). Señala la FALSA:",o:["No modifican la contractilidad cardiaca ni producen activación simpática refleja","Actúan sobre los lechos vasculares entéricos","Pueden provocar hiperpotasemia en casos de diabetes o insuficiencia renal","Pueden producir tos seca por acumulación de bradicinina"],a:1,
n:"Los IECA actúan preferentemente sobre los lechos vasculares del <b>riñón, el cerebro y el corazón</b> (donde la angiotensina II local tiene más peso), no sobre los entéricos. No cambian la contractilidad ni dan taquicardia refleja. Pueden causar hiperpotasemia (sobre todo con insuficiencia renal, diabetes, AINEs o espironolactona) y tos seca (↑ bradicinina)."},
{t:5,q:"IECA. Señala la FALSA:",o:["Producen activación simpática refleja","Actúan sobre los lechos vasculares de riñón, cerebro y corazón","Si producen tos seca es preferible sustituirlos por ARA-II","Son vasodilatadores mixtos: reducen la presión arterial, la precarga y la poscarga"],a:0,
n:"A diferencia de otros vasodilatadores (hidralazina, dihidropiridinas), los IECA <b>no producen activación simpática refleja</b> ni taquicardia: al bajar la angiotensina II también reducen el tono simpático. Son vasodilatadores mixtos (arteriales y venosos). Si dan tos seca (bradicinina), se cambian por un ARA-II (sartán), que no la produce."},
{t:5,q:"IECA. Señala la proposición INCORRECTA:",o:["Producen vasodilatación arterial y venosa","Disminuyen la remodelación cardiaca y renal","Pueden producir activación simpática refleja","Dosis elevadas pueden provocar azotemia"],a:2,
n:"Los IECA <b>no producen activación simpática refleja</b>. Dilatan arterias y venas, frenan el remodelado cardiaco y renal (efecto antiproliferativo) y, a dosis altas o con hipovolemia, pueden reducir la filtración glomerular (al dilatar la arteriola eferente) y causar <b>azotemia</b>."},
{t:5,q:"IECA. Señala la proposición INCORRECTA:",o:["Ocasionan vasodilatación venosa y vasoconstricción arterial","Aumentan la tolerancia al ejercicio físico","Tienen actividad nefroprotectora: son vasodilatadores e inhiben la remodelación","Disminuyen la precarga y la poscarga cardiaca"],a:0,
n:"Los IECA son vasodilatadores <b>mixtos</b>: dilatan arterias (↓ poscarga) <b>y</b> venas (↓ precarga). En el cardiópata mejoran la tolerancia al ejercicio y la supervivencia, y son nefroprotectores (reducen la presión intraglomerular y la proteinuria, y frenan la remodelación)."},
{t:5,q:"IECA. Señala la proposición INCORRECTA:",o:["Indicados en la disfunción ventricular y en la ICC al ser vasodilatadores mixtos","Contraindicados en la insuficiencia renal con oliguria o anuria","Tienen efecto cronotropo positivo por activación simpática","Tienen efectos antiproliferativos en la hipertrofia cardiaca y evitan el remodelado tras un infarto"],a:2,
n:"Los IECA <b>no tienen efecto cronotropo positivo</b>: no producen activación simpática refleja (incluso reducen el tono simpático). Se usan en la disfunción ventricular y la ICC, frenan la hipertrofia y el remodelado, y están contraindicados en la insuficiencia renal con oliguria o anuria (empeoran la filtración)."},
{t:5,q:"IECA. Señala la FALSA:",o:["Mantienen una perfusión hepática adecuada","Reducen la carga cardiaca y la presión arterial","No modifican la contractilidad cardiaca ni producen actividad simpática refleja","Evitan la retención de sodio y agua a nivel renal (diuresis y natriuresis)"],a:0,
n:"Los IECA actúan sobre los lechos vasculares <b>renal, cerebral y coronario</b>, cuya perfusión mantienen; el hígado no es su diana. Reducen la pre y la poscarga y la presión arterial sin tocar la contractilidad ni activar el simpático, y producen natriuresis y diuresis al bajar la aldosterona."},
{t:5,q:"¿Cuál de las siguientes reacciones adversas NO es provocada por los IECA?",o:["Tos seca por acúmulo de bradicinina","Hipotensión","Hipopotasemia","Azotemia"],a:2,
n:"Los IECA reducen la aldosterona y por eso <b>retienen potasio</b>: el riesgo es la <b>hiperpotasemia</b> (más con AINEs, espironolactona o insuficiencia renal), no la hipopotasemia. Otras reacciones: hipotensión (primera dosis, hipovolemia), azotemia y tos seca por la bradicinina."},
{t:5,q:"IECA. Señala la opción CORRECTA:",o:["Son los vasodilatadores de elección en la IR y actúan sobre vasos de capacidad y de resistencia, reduciendo la carga cardiaca y la presión arterial","Actúan sobre vasos de capacidad y de resistencia, reduciendo la carga cardiaca y la presión arterial, y disminuyen la contractilidad cardiaca","Pueden provocar insuficiencia renal y actúan preferentemente sobre los vasos del aparato digestivo","Disminuyen la contractilidad cardiaca y actúan preferentemente sobre los vasos del aparato digestivo"],a:0,d:true,
n:"En el test original había <b>varias respuestas correctas</b>; la clave de clase marca estas dos, que aquí van juntas.<br>✓ <b>Son los vasodilatadores de elección en la insuficiencia renal</b>: son nefroprotectores (bajan la presión intraglomerular y la proteinuria), siempre que no haya oliguria o anuria.<br>✓ Dilatan <b>vasos de capacidad</b> (venas, ↓ precarga) <b>y de resistencia</b> (arteriolas, ↓ poscarga): reducen la carga cardiaca y la presión arterial.<br>✗ No modifican la contractilidad y no actúan sobre todo en el aparato digestivo (sus lechos son riñón, cerebro y corazón).<br>Ojo: «pueden provocar insuficiencia renal» no está marcada en la clave, aunque es cierto que pueden empeorar la función renal si hay hipovolemia, oliguria o dosis altas (azotemia). Si en el examen hay que marcar varias, la clave marca la de elección en la IR y la de vasos de capacidad y resistencia."},
{t:5,q:"¿Cuál NO es un efecto beneficioso de los IECA en los cardiópatas?",o:["Mejoran la hemodinámica al producir vasodilatación arterial y venosa","Son nefroprotectores","Aumentan la remodelación cardiaca y renal","Aumentan la tolerancia al ejercicio"],a:2,
n:"Los IECA <b>disminuyen</b> (no aumentan) la remodelación cardiaca y renal: la angiotensina II y la aldosterona estimulan la hipertrofia y la fibrosis, y los IECA las frenan. Además mejoran la hemodinámica (vasodilatación mixta), protegen el riñón y aumentan la tolerancia al ejercicio y la supervivencia."},
{t:5,q:"Sartanes (ARA-II). Señala la proposición INCORRECTA:",o:["Son antagonistas puros del receptor AT2","Sustituyen adecuadamente a los IECA cuando aparece tos seca","Tienen efecto antihipertensivo, antiproliferativo y antiapoptótico","Inhiben el efecto vasopresor de la angiotensina II y la liberación de aldosterona"],a:0,
n:"Los sartanes (losartán, telmisartán, valsartán…) son antagonistas puros del receptor <b>AT1</b>. Al dejar libre el AT2 se potencian sus efectos beneficiosos (vasodilatación, antiproliferación). No aumentan la bradicinina, así que no dan tos: sustituyen al IECA cuando aparece.<br><i>Pregunta incompleta en el original; se ha completado.</i>"},
{t:5,q:"Señala la INCORRECTA sobre los β-bloqueantes:",o:["No alteran la conducción AV","Previenen la taquicardia refleja y disminuyen las despolarizaciones prematuras","Pueden producir broncoespasmo y efecto inotropo negativo","Reducen los efectos nocivos de la hipertrofia ventricular"],a:0,
n:"Los β-bloqueantes (clase II) <b>enlentecen la conducción AV</b> (efecto dromotropo negativo) y alargan el periodo refractario del nodo: por eso controlan la frecuencia en las arritmias supraventriculares y pueden provocar bloqueos AV. También reducen los ectópicos y la taquicardia refleja; dan broncoespasmo (los no selectivos) e inotropismo negativo."},
{t:5,q:"Bloqueantes β. Señala la opción CORRECTA:",o:["Se usan en arritmias ventriculares y pueden agravar una ICC","Se usan en arritmias ventriculares y tienen efecto inotropo positivo","Pueden agravar una ICC y pueden ocasionar hipertensión","Tienen efecto inotropo positivo y pueden ocasionar hipertensión"],a:0,
n:"En el test original había <b>varias respuestas correctas</b>; aquí van juntas en una sola opción.<br>✓ Se usan en <b>arritmias ventriculares</b> (y supraventriculares): reducen el automatismo y los ectópicos.<br>✓ Por su efecto <b>inotropo negativo</b> pueden <b>descompensar una ICC</b>; en la insuficiencia cardiaca solo se introducen cuando está estable y a dosis muy bajas (carvedilol).<br>✗ No son inotropos positivos.<br>✗ Son <b>hipotensores</b>, no hipertensores."},
{t:5,q:"Los β-bloqueantes. Señala la proposición INCORRECTA:",o:["Reducen los efectos nocivos de la hipertrofia ventricular","Previenen la taquicardia refleja y las despolarizaciones prematuras","Pueden producir depresión cardiaca e hipotensión","Pueden potenciar la recurrencia de taquicardias por aumento de la actividad simpática"],a:3,
n:"Los β-bloqueantes <b>bloquean</b> la acción del simpático sobre el corazón: previenen taquicardias y extrasístoles. Lo que sí puede ocurrir es un <b>efecto rebote</b> (taquicardia, arritmias) si se suspenden bruscamente, por el aumento de receptores β; por eso se retiran poco a poco. Sus riesgos: depresión cardiaca, bradicardia, hipotensión y broncoespasmo."},
{t:5,q:"Señala la INCORRECTA sobre los β-bloqueantes:",o:["Previenen la taquicardia refleja y disminuyen las despolarizaciones prematuras","Están indicados en arritmias supraventriculares y en la intoxicación digitálica","Están contraindicados en la hipertrofia ventricular secundaria a estenosis aórtica","Pueden provocar broncoespasmo e hipotensión"],a:2,
n:"En la estenosis aórtica (subaórtica en el perro) y en la cardiomiopatía hipertrófica, los β-bloqueantes (atenolol) <b>están indicados</b>: reducen la frecuencia y la demanda de O₂, mejoran el llenado diastólico y disminuyen el riesgo de arritmias y muerte súbita. También se usan en arritmias supraventriculares y en las arritmias de la intoxicación digitálica."},
{t:5,q:"Bloqueantes β-adrenérgicos. Señala la proposición INCORRECTA:",o:["En la estenosis aórtica pueden reducir la hipertrofia cardiaca y mejorar la función diastólica","Los selectivos β1 no provocan broncoespasmo","Se utilizan en la intoxicación digitálica","Pueden asociarse con seguridad a los bloqueantes de los canales lentos de Ca²⁺"],a:3,d:true,
n:"β-bloqueantes + verapamilo o diltiazem: los dos son <b>crono, dromo e inotropos negativos</b> y juntos pueden causar bradicardia grave, bloqueo AV e insuficiencia cardiaca: <b>no es una asociación segura</b>. Los selectivos β1 (atenolol, metoprolol) prácticamente no producen broncoespasmo a dosis terapéuticas (a dosis altas pierden selectividad).<br>Discutible: a dosis altas los β1 selectivos pierden selectividad y pueden dar broncoespasmo. Si tu profesor consideraba también falsa esa opción, la respuesta completa sería «los selectivos β1 no provocan broncoespasmo» y «pueden asociarse con seguridad a los bloqueantes del Ca²⁺»."},
{t:5,q:"Antiarrítmicos de clase II (β-bloqueantes). Señala la FALSA:",o:["Están contraindicados en el asma porque pueden provocar broncoespasmo","Enlentecen la conducción AV y previenen la taquicardia refleja","Pueden producir hipertensión","Pueden provocar depresión cardiaca por su efecto inotropo negativo"],a:2,
n:"Los β-bloqueantes son <b>hipotensores</b> (↓ gasto cardiaco y ↓ renina): pueden producir hipotensión, no hipertensión. Enlentecen el nodo AV, frenan la taquicardia refleja, deprimen la contractilidad y, los no selectivos, provocan broncoespasmo (contraindicados en el asma)."},
{t:5,q:"Verapamilo y diltiazem. Señala la proposición CORRECTA:",o:["Tienen actividad inotropa positiva","Su asociación con β-bloqueantes es segura","Pueden provocar hipertensión","Están indicados en la cardiomiopatía hipertrófica"],a:3,
n:"Verapamilo y diltiazem (cationes anfófilos, clase IV) son <b>inotropos, cronotropos y dromotropos negativos</b> y vasodilatadores: mejoran la relajación y el llenado del ventrículo, por eso se usan en la <b>cardiomiopatía hipertrófica</b> (diltiazem en el gato) y en taquicardias supraventriculares. No se asocian a β-bloqueantes. Pueden causar hipotensión."},
{t:5,q:"Bloqueantes de los canales lentos de Ca²⁺, antiarrítmicos de clase IV (verapamilo y diltiazem). Señala la INCORRECTA:",o:["Producen una acción intensa depresora de la conducción AV","Poseen actividad inotropa negativa","Son de elección en arritmias supraventriculares graves y agudas","Se usan junto con β-bloqueantes"],a:3,
n:"Verapamilo y diltiazem <b>no se combinan con β-bloqueantes</b>: se suman los efectos negativos sobre el nodo AV y la contractilidad (bloqueo AV, bradicardia grave, ICC). Deprimen mucho la conducción AV, son inotropos negativos y son de elección en las taquicardias supraventriculares agudas."},
{t:5,q:"Bloqueantes de los canales lentos de Ca²⁺ (verapamilo y diltiazem). Señala la proposición INCORRECTA:",o:["Tienen actividad inotrópica y cronotropa negativa","Están contraindicados en la ICC severa","Su asociación con β-bloqueantes es segura en la intoxicación digitálica","Se utilizan en la CMP hipertrófica y en taquicardias supraventriculares"],a:2,
n:"En la <b>intoxicación digitálica</b> el nodo AV ya está deprimido: el verapamilo está contraindicado (además aumenta la concentración de digoxina) y combinarlo con β-bloqueantes es aún más peligroso. Verapamilo y diltiazem son inotropos y cronotropos negativos, se evitan en la ICC grave y se usan en la CMH y las taquicardias supraventriculares."},
{t:5,q:"Los arteriodilatadores antagonistas del calcio NO vasoselectivos:",o:["Generan taquicardia refleja","Tienen actividad antiarrítmica","De ellos, los más utilizados son los nitratos","Carecen de utilidad clínica en veterinaria"],a:1,
n:"Los antagonistas del Ca²⁺ <b>no vasoselectivos</b> (verapamilo, diltiazem) actúan también sobre el corazón: deprimen los nodos SA y AV, así que son <b>antiarrítmicos</b> (clase IV) y no dan taquicardia refleja. La taquicardia refleja es propia de los vasoselectivos (dihidropiridinas). Los nitratos son otro grupo (donadores de NO). El diltiazem se usa mucho en veterinaria (CMH felina, fibrilación auricular)."},
{t:5,q:"Arteriodilatadores antagonistas del calcio vasoselectivos. Señala la FALSA:",o:["Generan taquicardia refleja","Tienen actividad antiarrítmica","Son útiles en la hipertensión y en la profilaxis del infarto de miocardio","Tienen utilidad en veterinaria"],a:1,
n:"Las dihidropiridinas (amlodipino, nifedipino, nimodipino) son <b>vasoselectivas</b>: casi no actúan sobre los nodos SA y AV, así que <b>no son antiarrítmicas</b>, y la vasodilatación provoca taquicardia refleja. Se usan en la hipertensión (el amlodipino es de elección en el gato) y en la cardiopatía isquémica.<br>Una clave de clase marca «generan taquicardia refleja», pero es cierta: las dihidropiridinas sí la producen (en otra pregunta del parcial, «no provocan taquicardia refleja» es la opción falsa)."},
{t:5,q:"¿Cuál de los siguientes antagonistas del calcio NO es vasoselectivo?",o:["Nifedipino","Verapamilo","Amlodipino","Felodipino"],a:1,
n:"El <b>verapamilo</b> (fenilalquilamina) y el diltiazem (benzotiazepina) son cationes anfófilos <b>no vasoselectivos</b>: actúan sobre los vasos y el corazón. Nifedipino, amlodipino y felodipino son dihidropiridinas (terminan en «-dipino»), vasoselectivas."},
{t:5,q:"Los antagonistas del Ca²⁺ NO vasoselectivos (verapamilo):",o:["Son venodilatadores","Pueden provocar taquicardia refleja","Están contraindicados en el bloqueo cardiaco","Se pueden utilizar de forma segura con β-bloqueantes"],a:2,
n:"Como el verapamilo deprime el nodo AV, está <b>contraindicado en los bloqueos AV</b>, el síndrome del seno enfermo y la ICC grave. Es sobre todo arteriodilatador (no venodilatador) y no causa taquicardia refleja porque frena el corazón. No debe asociarse a β-bloqueantes."},
{t:5,q:"¿Cuál de los siguientes NO es un efecto tóxico de los digitálicos?",o:["Vómitos","Ginecomastia y galactorrea","Vasodilatación arterial mesentérica","Extrasístoles"],a:2,
n:"Los digitálicos producen <b>vasoconstricción</b> mesentérica (pueden causar isquemia intestinal), no vasodilatación. Toxicidad típica: digestiva (anorexia, vómitos, diarrea; lo primero que aparece en el perro), cardiaca (extrasístoles, bloqueos, taquicardia ventricular), visual y neurológica. Por su estructura esteroidea pueden dar ginecomastia y galactorrea."},
{t:5,q:"Digitálicos. Señala la INCORRECTA:",o:["Efecto inotropo y batmotropo positivos","Aumentan el gasto cardiaco sin aumentar el consumo de oxígeno","Aumentan la formación de impulsos ectópicos","Aceleran la velocidad de conducción auriculoventricular"],a:3,
n:"Los digitálicos <b>enlentecen la conducción AV</b> (dromotropo negativo, por efecto vagal y directo); por eso controlan la frecuencia en la fibrilación auricular. Son inotropos y batmotropos positivos (↑ excitabilidad: ectópicos a dosis altas). En el corazón insuficiente aumentan el gasto sin aumentar el consumo de O₂ (el corazón se vuelve más pequeño y eficiente)."},
{t:5,q:"La toxicidad de los digitálicos se incrementa en:",o:["Estados febriles","Aumento del metabolismo","Hipopotasemia","Hipocalcemia"],a:2,
n:"El K⁺ compite con la digoxina por la Na⁺/K⁺-ATPasa: con el <b>potasio bajo</b> (diuréticos de asa, vómitos) se une más digoxina y aumenta la toxicidad. También la aumentan la <b>hipercalcemia</b> (no la hipocalcemia), la hipomagnesemia, el hipotiroidismo y la insuficiencia renal; la hiperpotasemia la reduce."},
{t:5,q:"Los digitálicos están contraindicados en:",o:["Estenosis aórtica","Fibrilación auricular","Insuficiencia cardiaca secundaria a miocarditis","Insuficiencia cardiaca congestiva"],a:0,d:true,
n:"Los digitálicos están contraindicados en las obstrucciones del tracto de salida (<b>estenosis aórtica</b>, cardiomiopatía hipertrófica), en las arritmias ventriculares y en los bloqueos AV. Su indicación clásica es la ICC con <b>fibrilación auricular</b>. En la IC por miocarditis son poco eficaces y más arritmogénicos, así que se usan con precaución.<br>Discutible: algunos textos incluyen la IC por miocarditis entre las contraindicaciones. Si tu profesor la daba también por buena, la respuesta completa sería «estenosis aórtica e IC secundaria a miocarditis»."},
{t:5,q:"¿Cuándo NO están contraindicados los digitálicos?",o:["Estenosis hipertrófica subaórtica","Taquicardia o fibrilación ventricular","Miocardiopatía hipertrófica","ICC (insuficiencia cardiaca congestiva)"],a:3,
n:"Los digitálicos sí se usan en la <b>ICC</b>, sobre todo cuando hay fibrilación auricular o taquicardia supraventricular. Están contraindicados en la estenosis subaórtica y la cardiomiopatía hipertrófica (al aumentar la contractilidad empeoran la obstrucción) y en las arritmias ventriculares (aumentan los ectópicos)."},
{t:5,q:"Glucósidos cardiotónicos. Señala la CORRECTA:",o:["Disminuyen los impulsos en el nodo SA","Disminuyen la demanda de oxígeno del miocardio","Su dosis debe aumentarse en la hipopotasemia","No deben asociarse en ningún caso a diuréticos"],a:0,d:true,
n:"Por su efecto vagal, los digitálicos <b>enlentecen el nodo sinusal</b> (cronotropo negativo) y la conducción AV. Aumentan el gasto sin aumentar el consumo de O₂ (no lo reducen). En la hipopotasemia hay que <b>reducir</b> la dosis o corregir el K⁺, porque aumenta la toxicidad. Se asocian a menudo a diuréticos, vigilando el potasio.<br>Discutible: en el corazón insuficiente el consumo de O₂ no aumenta e incluso puede disminuir (el corazón se hace más pequeño). Si tu profesor daba también por buena esa opción, la respuesta completa sería «disminuyen los impulsos del nodo SA y la demanda de O₂»."},
{t:5,q:"Los glucósidos cardiotónicos disminuyen:",o:["La fuerza contráctil del corazón","El ritmo cardiaco","El tono vagal","El consumo cardiaco de oxígeno"],a:1,d:true,
n:"Los glucósidos cardiotónicos <b>disminuyen la frecuencia cardiaca</b>: aumentan el tono vagal y, al mejorar el gasto, reducen la activación simpática. Aumentan la fuerza de contracción (inotropo positivo) y en el corazón insuficiente mejoran el gasto sin aumentar el consumo de O₂.<br>Discutible: en el corazón insuficiente el consumo de O₂ no aumenta e incluso puede disminuir. Si tu profesor daba también por buena esa opción, la respuesta completa sería «el ritmo cardiaco y el consumo de O₂»."},
{t:5,q:"Los glucósidos cardiotónicos están indicados en:",o:["Miocardiopatía hipertrófica","ICC asociada a fibrilación auricular","Estenosis aórtica","Taquicardia o fibrilación ventricular"],a:1,
n:"La indicación clásica de la digoxina es la <b>ICC con fibrilación auricular</b> (o flúter con respuesta ventricular rápida): refuerza la contracción y, al frenar el nodo AV, baja la frecuencia ventricular. Está contraindicada en la CMH, la estenosis aórtica y las arritmias ventriculares."},
{t:5,q:"Metilxantinas (teofilina). Señala la FALSA:",o:["Son de 2ª elección en el asma","Inducen una broncodilatación más efectiva en las vías de gran calibre","Son estimulantes del SNC y del miocardio","Poseen un margen de seguridad estrecho"],a:1,
n:"Por descarte: las otras tres son ciertas. La teofilina y la aminofilina relajan el músculo liso bronquial (inhiben las fosfodiesterasas y bloquean los receptores de adenosina) y su efecto no es mayor en las vías grandes (se describe como más útil en las pequeñas). Son de <b>2ª elección</b> tras los corticoides y los β2-agonistas, <b>estimulan el SNC y el corazón</b> (nerviosismo, taquicardia, arritmias, convulsiones) y tienen un <b>margen terapéutico estrecho</b>."},
{t:5,q:"Fármacos inotrópicos. Señala la proposición INCORRECTA:",o:["La dobutamina tiene más acción inotropa que cronotropa y cierta actividad vasodilatadora","El desmetil-pimobendan posee actividad inotrópica positiva al inhibir las PDE","La dobutamina con bajas dosis de dopamina puede ser útil para aumentar el flujo renal","La dopamina a dosis altas es vasoconstrictora y presenta actividad cronotropa e inotropa positiva, aumentando la demanda de oxígeno"],a:1,d:true,
n:"Según el temario, la acción <b>inotropa</b> del pimobendan se debe sobre todo a que <b>sensibiliza la troponina C al Ca²⁺</b>, mientras que su metabolito desmetilado inhibe la PDE III y V y aporta la acción <b>vasodilatadora</b>. Es discutible porque la inhibición de la PDE3 también contribuye algo al inotropismo. El resto es cierto: la dobutamina es más inotropa que cronotropa; dobutamina con dopamina a dosis bajas mejora el flujo renal; la dopamina a dosis altas es vasoconstrictora (α1)."},
{t:5,q:"Dobutamina. Señala la CORRECTA:",o:["Se usa en la IC leve administrada por vía oral","Posee un efecto cronotropo marcado","En la ICC con fibrilación auricular asociada, hay que administrar antes digitálicos","Tiene un efecto vasodilatador potente, por lo que puede generar hipotensión"],a:2,
n:"La dobutamina facilita la conducción AV: si hay <b>fibrilación auricular</b> dispararía la frecuencia ventricular, por eso antes se <b>digitaliza</b> (o se da diltiazem) para frenar el nodo AV. Solo se usa en infusión IV continua (vida media de minutos) en la IC grave o el shock cardiogénico; es más inotropa que cronotropa y su efecto vasodilatador es leve."},
{t:5,q:"Pimobendan. Señala la INCORRECTA:",o:["Puede provocar arritmias","Actividad inotropa y vasodilatadora potente sin aumento del consumo de O₂","Indicado en la cardiomiopatía hipertrófica o la estenosis aórtica leve","Inhibe la agregación plaquetaria"],a:2,
n:"El pimobendan está <b>contraindicado</b> en la cardiomiopatía hipertrófica y en la estenosis aórtica: aumentar la contractilidad empeora la obstrucción del tracto de salida. Está indicado en la ICC por enfermedad valvular mitral y en la cardiomiopatía dilatada. Es inodilatador sin aumentar el consumo de O₂, inhibe la agregación plaquetaria (PDE3) y puede ser arritmogénico."},
{t:5,q:"Inodilatadores de acción dual (pimobendan). Señala la FALSA:",o:["Son útiles en la ICC debida a cardiopatía dilatada","Aumentan el consumo de oxígeno","Los β-bloqueantes atenúan su efecto","Están contraindicados en las cardiomiopatías hipertróficas o la estenosis aórtica"],a:1,
n:"La gran ventaja del pimobendan: como sensibiliza la troponina al Ca²⁺ (sin subir tanto el Ca²⁺ intracelular) y además dilata los vasos, mejora la contracción <b>sin aumentar el consumo de O₂</b> del miocardio. Se usa en la cardiopatía dilatada y la enfermedad mitral; su efecto lo atenúan los β-bloqueantes y los antagonistas del Ca²⁺; está contraindicado en la CMH y la estenosis aórtica."},
{t:5,q:"Inodilatadores de acción dual (pimobendan). Señala la proposición INCORRECTA:",o:["Puede ser arritmogénico a dosis terapéuticas","Es un vasodilatador potente de tipo mixto","Los antagonistas del calcio atenúan su efecto","Está contraindicado en cardiomiopatías hipertróficas o estenosis aórtica"],a:0,
n:"A dosis terapéuticas el pimobendan <b>apenas es arritmogénico</b> (una de sus ventajas frente a otros inotropos); las arritmias aparecen con dosis altas. Es un vasodilatador mixto potente, su efecto lo reducen los antagonistas del Ca²⁺ y los β-bloqueantes, y está contraindicado en la CMH y la estenosis aórtica."},
{t:5,q:"Pimobendan. Señala la CORRECTA:",o:["Los antagonistas del calcio y los β-antagonistas reducen su efecto","Aumenta el consumo miocárdico de oxígeno","Es cronotropo positivo y aumenta la presión de precarga","Está indicado en la cardiomiopatía hipertrófica"],a:0,
n:"Según el temario, los <b>antagonistas del Ca²⁺</b> (verapamilo, diltiazem) y los <b>β-bloqueantes</b> atenúan el efecto del pimobendan. No aumenta el consumo de O₂, apenas modifica la frecuencia, <b>reduce</b> la precarga y la poscarga (vasodilatador mixto) y está contraindicado en la CMH."},
{t:5,q:"Inhibidores de la PDE3 (amrinona y milrinona). Señala la FALSA:",o:["Se usan para el tratamiento a corto plazo por ser proarrítmicos","Tienen mayor acción inotropa que vasodilatadora","Tienen escasa actividad sobre el cronotropismo","Pueden provocar trombocitopenia e hipotensión"],a:1,
n:"Amrinona y milrinona son «inodilatadores» con <b>más acción vasodilatadora que inotropa</b>. Se usan solo a corto plazo (IV) en la IC descompensada porque a largo plazo aumentan las arritmias y la mortalidad. Apenas cambian la frecuencia. Efectos adversos: arritmias, hipotensión y trombocitopenia (sobre todo la amrinona)."},
{t:5,q:"Inhibidores de la PDE3 (milrinona…). Señala la proposición INCORRECTA:",o:["Son fármacos inotropos y cronotropos positivos","Son de utilidad en la descompensación de la ICC, no de forma crónica","Disminuyen la resistencia vascular sistémica y pulmonar","Pueden aumentar el consumo de oxígeno por aumento de la presión en la aurícula izquierda"],a:3,d:true,
n:"La milrinona <b>reduce</b> la precarga y la poscarga, y con ellas la presión de llenado de la aurícula izquierda: no aumenta el consumo de O₂ por esa vía. Es inotropa positiva (con un efecto cronotropo escaso, de ahí la duda con la opción A), disminuye la resistencia vascular sistémica y pulmonar y se usa solo a corto plazo en la ICC descompensada.<br><i>En el original el enunciado decía «activadores» de la PDE3; son <b>inhibidores</b>.</i>"},
{t:5,q:"Inotropos e inodilatadores. Señala la INCORRECTA:",o:["La dopamina se usa en infusión intravenosa un máximo de 72 h","La dobutamina tiene más acción vasodilatadora que inotropa positiva","La milrinona sufre escaso metabolismo hepático y también se usa en infusión","Los antagonistas del calcio atenúan el efecto del pimobendan"],a:1,
n:"La dobutamina es <b>más inotropa que vasodilatadora</b> (al revés que la amrinona y la milrinona, que son más vasodilatadoras). La dopamina se desensibiliza a las ~72 h; la milrinona se elimina sobre todo sin cambios por el riñón y se da en infusión; los antagonistas del Ca²⁺ reducen el efecto del pimobendan."},
{t:5,q:"Dopamina. Señala la proposición INCORRECTA:",o:["Se utiliza en la ICC grave asociada a congestión pulmonar e hipoperfusión tisular","Dosis muy altas pueden provocar hipotensión y bradicardia","Asociada a nitroprusiato permite aumentar el flujo renal y el inotropismo cardiaco, reduciendo la resistencia periférica","Posee una semivida corta, por lo que hay que administrarla en infusión continua"],a:1,
n:"Las dosis <b>muy altas</b> de dopamina estimulan los receptores α1: producen <b>vasoconstricción, hipertensión y taquiarritmias</b>. La hipotensión y la bradicardia (D2) se describen con dosis bajas. Su vida media es de minutos (infusión continua) y se usa en la ICC grave con hipoperfusión, a veces asociada a nitroprusiato."},
{t:5,q:"Fármacos arteriodilatadores:",o:["Aumentan la presión arterial","Aumentan el trabajo cardiaco","Disminuyen la presión de precarga","Disminuyen la presión de poscarga"],a:3,
n:"Los arteriodilatadores (hidralazina, amlodipino) dilatan los vasos de resistencia: bajan la presión arterial y la <b>poscarga</b>, y así reducen el trabajo del corazón. Los que bajan sobre todo la <b>precarga</b> son los venodilatadores (nitratos). IECA, nitroprusiato y prazosina son mixtos."},
{t:5,q:"Acciones cardiovasculares de los nitratos orgánicos. Señala la INCORRECTA:",o:["A nivel coronario previenen o revierten el vasoespasmo","Reducen la precarga y la poscarga cardiaca","Aumentan la presión venosa sistémica","Tienen un efecto débil sobre la presión arterial"],a:2,
n:"Los nitratos dilatan sobre todo las <b>venas</b>: la sangre se queda en el lecho venoso, así que <b>bajan</b> la presión venosa y la precarga (menos congestión). A dosis bajas apenas cambian la presión arterial. En las coronarias previenen o revierten el espasmo y dilatan los vasos colaterales."},
{t:5,q:"Los nitratos orgánicos (dilatadores coronarios). Señala la INCORRECTA:",o:["Son útiles en crisis agudas hipertensivas, ICC e infarto","Son vasodilatadores mixtos con mayor actividad sobre arterias, reduciendo la poscarga","Disminuyen la demanda de oxígeno a nivel cardiaco","A nivel coronario tienen utilidad para prevenir y revertir el vasoespasmo"],a:1,
n:"Los nitratos son vasodilatadores mixtos con <b>predominio venoso</b>: reducen sobre todo la <b>precarga</b> (y en menor medida la poscarga). Así bajan la tensión de la pared y la <b>demanda de O₂</b>. Se usan en crisis hipertensivas, ICC aguda (edema pulmonar) e infarto, y previenen el vasoespasmo coronario."},
{t:5,q:"Los nitratos orgánicos. Señala la proposición CORRECTA:",o:["Presentan poca capacidad de atravesar membranas biológicas","Se suelen administrar por vía oral en comprimidos","Provocan dilatación de los vasos colaterales de forma preferencial","Disminuyen el flujo sanguíneo de las zonas isquémicas"],a:2,
n:"Los nitratos dilatan de forma preferente las grandes coronarias y los <b>vasos colaterales</b>, y redistribuyen la sangre hacia las <b>zonas isquémicas</b> (aumentan su flujo). Además previenen el vasoespasmo y tienen cierta acción antiagregante. Son muy liposolubles (atraviesan bien las membranas, incluso la piel): la nitroglicerina se da sublingual, transdérmica o IV, porque por vía oral sufre un gran efecto de primer paso."},
{t:5,q:"Activadores de los canales de potasio (minoxidil…). Señala la proposición INCORRECTA:",o:["Son de utilidad en la ICC","Son arteriodilatadores de acción potente y prolongada","Son fármacos de reserva en la hipertensión arterial grave refractaria a otros tratamientos","Aumentan el tono simpático como respuesta refleja (aumentando el gasto cardiaco)"],a:0,
n:"El minoxidil abre los canales de K⁺ del músculo liso arteriolar: es un <b>arteriodilatador potente</b> que provoca taquicardia refleja y retención de Na⁺ y agua. Por eso <b>no se usa en la ICC</b> y se reserva para la hipertensión grave refractaria, asociado a β-bloqueantes y diuréticos."},
{t:5,q:"Otros vasodilatadores. Señala la proposición INCORRECTA:",o:["Prazosina, bloqueante α1, es útil en la ICC de origen valvular","Isoxsuprina es un arteriodilatador en vasos del músculo esquelético, útil en la infosura","Nicergolina es un vasodilatador cerebral usado en problemas geriátricos de comportamiento","Sildenafilo, inhibidor de la PDE5, es útil para el tratamiento agudo del fallo cardiaco"],a:3,
n:"El <b>sildenafilo</b> (inhibidor de la PDE5) dilata sobre todo los vasos <b>pulmonares</b>: se usa en la hipertensión pulmonar del perro, no en el fallo cardiaco agudo (para eso, dobutamina o milrinona).<br>• Prazosina: vasodilatador mixto (α1).<br>• Isoxsuprina: laminitis (infosura) del caballo.<br>• Nicergolina: vasodilatador cerebral para el deterioro cognitivo del perro mayor."},
{t:5,q:"¿Cuál es una posible reacción adversa al usar hidralazina? Señala la CORRECTA:",o:["Aumento del riesgo de hiperglucemia","Riesgo de hipotensión con IECA, anestésicos y β-bloqueantes","Aumento de la presión arterial con diuréticos","Reducción del efecto de los bloqueantes de los canales de Ca²⁺"],a:1,
n:"La hidralazina es un arteriodilatador directo potente: combinada con otros fármacos que bajan la presión (<b>IECA, anestésicos, β-bloqueantes, diuréticos, antagonistas del Ca²⁺</b>) suma sus efectos y aparece hipotensión. Por eso se empieza con dosis bajas y se mide la presión."},
{t:5,q:"Los glucósidos cardiotónicos están indicados y son eficaces en:",o:["IC y fibrilación auricular con insuficiencia ventricular aguda, e ICC no complicada y flúter con respuesta ventricular rápida","Arritmias ventriculares graves, miocardiopatía hipertrófica y estenosis mitral aislada con miocardiopatía","ICC no complicada y flúter con respuesta ventricular rápida, y arritmias ventriculares graves","IC y fibrilación auricular con insuficiencia ventricular aguda, y miocardiopatía hipertrófica"],a:0,d:true,
n:"En el test original había <b>varias respuestas correctas</b>; aquí van juntas en una sola opción.<br>✓ <b>IC con fibrilación auricular</b>: la digoxina refuerza la contracción y, al frenar el nodo AV, baja la frecuencia ventricular.<br>✓ <b>ICC no complicada y flúter con respuesta ventricular rápida</b>: por el mismo motivo.<br>✗ Contraindicados en las <b>arritmias ventriculares</b> (aumentan los ectópicos) y en la <b>miocardiopatía hipertrófica</b> (empeoran la obstrucción).<br>✗ Poco eficaces en la <b>estenosis mitral aislada</b> con ritmo sinusal y en las miocardiopatías.<br>Discutible el matiz de la «insuficiencia ventricular aguda»: en la IC aguda la digoxina actúa despacio y se prefieren otros inotropos, salvo para controlar la frecuencia de una fibrilación auricular rápida."},
{t:5,q:"Los nitratos orgánicos. Señala la CORRECTA:",o:["Presentan poca capacidad de atravesar membranas biológicas","Se suelen administrar por vía oral en comprimidos","Evitan las estenosis espasmódicas de las coronarias y tienen actividad antiagregante","Disminuyen el flujo sanguíneo de las zonas isquémicas"],a:2,
n:"Los nitratos (donadores de NO) <b>previenen y revierten el espasmo</b> de las coronarias y, al aumentar el GMPc de las plaquetas, tienen cierta <b>acción antiagregante</b>. También dilatan de forma preferente los vasos colaterales y <b>aumentan</b> el flujo de las zonas isquémicas. Son muy liposolubles (atraviesan bien las membranas, incluso la piel): la nitroglicerina se da sublingual, transdérmica o IV, porque por vía oral sufre un gran primer paso."},
/* ---------- Preguntas añadidas del pack de 4 PDF (PREGUNTAS, RECO, 2021, octubre 2022) ---------- */
{t:5,q:"Los digitálicos son eficaces en:",o:["Estenosis mitral aislada","Miocardiopatía restrictiva","ICC secundaria a cardiopatía hipertensiva","Pericarditis constrictiva o deformante"],a:2,
n:"Los digitálicos son eficaces en la <b>ICC con disfunción sistólica</b>, por ejemplo la secundaria a cardiopatía hipertensiva o valvular, y sobre todo si hay fibrilación auricular. Son poco eficaces cuando el problema es de <b>llenado</b> y no de bombeo: estenosis mitral aislada en ritmo sinusal, miocardiopatía restrictiva y pericarditis constrictiva."},
{t:3,q:"¿Cuál de los siguientes fármacos es un modificador biológico de la artritis reumatoide?",o:["Etanercept","Metotrexato","Leflunomida","Sulfasalazina"],a:0,
n:"El <b>etanercept</b> es un FAME <b>biológico</b>: una proteína de fusión que actúa como receptor soluble del TNF. Metotrexato, leflunomida y sulfasalazina son FAME <b>sintéticos convencionales</b>."},
{t:5,q:"Antiarrítmicos de clase II (β-bloqueantes):",o:["Pueden generar hipotensión","Generan hipertensión","Provocan broncodilatación","No se usan en veterinaria"],a:0,
n:"Los β-bloqueantes son <b>hipotensores</b> (↓ gasto cardiaco y ↓ renina) y pueden dar hipotensión. Los no selectivos producen <b>broncoconstricción</b>. Se usan mucho en veterinaria: atenolol en la CMH felina y la estenosis subaórtica, sotalol en arritmias ventriculares…"},
{t:4,q:"¿Cuál NO es un efecto de los glucocorticoides?",o:["Son hipotensores","Producen linfopenia","Inhiben la liberación de STH y TSH","Son orexígenos"],a:0,
n:"Los GC son <b>hipertensores</b>: retienen Na⁺ y agua y aumentan la reactividad vascular a las catecolaminas. Sí producen <b>linfopenia</b> (leucograma de estrés), <b>inhiben la liberación de STH</b> (hormona del crecimiento) <b>y de TSH</b>, y son <b>orexígenos</b> (aumentan el apetito)."},
{t:4,q:"Efectos de los glucocorticoides. Señala la INCORRECTA:",o:["Aumentan la filtración glomerular, pero también la reabsorción tubular de sodio en la nefrona","Aumentan la reactividad a las catecolaminas, lo que provoca vasoconstricción y, de forma indirecta, efectos crono e inotropos positivos","Disminuyen la actividad paratiroidea","Bloquean la liberación de STH, por lo que inhiben el crecimiento"],a:2,
n:"Los GC <b>aumentan</b> la actividad paratiroidea: al reducir la absorción intestinal de calcio y aumentar su excreción renal provocan un hiperparatiroidismo secundario. Lo demás es cierto: ↑ filtración glomerular con ↑ reabsorción de Na⁺, efecto permisivo sobre las catecolaminas (vasoconstricción y efectos crono e inotropos positivos indirectos) y bloqueo de la STH, por lo que frenan el crecimiento de los animales jóvenes."},
{t:5,q:"Antiarrítmicos de clase III (amiodarona, sotalol, bretilio). Señala la CORRECTA:",o:["Prolongan el potencial de acción y el periodo refractario","Acortan el potencial de acción y el periodo refractario","Bloquean los canales lentos de calcio del nodo AV","Aumentan la velocidad de despolarización de la fase 0"],a:0,
n:"Los antiarrítmicos de clase III bloquean los canales de K⁺: <b>retrasan la repolarización</b> y así <b>prolongan el potencial de acción y el periodo refractario</b>. Los que bloquean los canales lentos de Ca²⁺ son los de clase IV (verapamilo, diltiazem), y los de clase I (bloqueantes de Na⁺) <b>disminuyen</b> la velocidad de la fase 0."},
{t:5,q:"Pimobendan. Señala la FALSA:",o:["Posee una potente actividad antiagregante plaquetaria","Aumenta el consumo miocárdico de oxígeno","Es inotropo y vasodilatador potente","Está indicado en la cardiomiopatía dilatada y la insuficiencia valvular"],a:1,
n:"El pimobendan <b>no aumenta el consumo de O₂</b> del miocardio (la clave de clase anota «disminuye»): sensibiliza la troponina al Ca²⁺ y además dilata los vasos. Es inotropo y vasodilatador potente, inhibe la agregación plaquetaria (PDE3) y está indicado en la cardiomiopatía dilatada y la insuficiencia valvular."},
{t:2,q:"Señala la proposición INCORRECTA sobre el péptido natriurético auricular (ANP):",o:["Inhibe la secreción de aldosterona","Se sintetiza en los miocitos auriculares ante sobrecargas de volumen en la aurícula derecha","Produce pérdida de potasio","Tiene actividad diurética y natriurética rápida sobre el glomérulo"],a:2,
n:"El ANP produce natriuresis y diuresis <b>sin pérdida de potasio</b> (no da hipopotasemia), en parte porque inhibe la aldosterona. Lo sintetizan los <b>miocitos auriculares</b> cuando la aurícula se distiende por exceso de volumen, y también inhibe la renina y la vasopresina."},
{t:4,q:"Glucocorticoides. Señala la proposición FALSA:",o:["Aumentan la glucemia y el glucógeno hepático","Disminuyen la excreción renal de calcio","Aumentan la actividad paratiroidea","Inducen catabolismo proteico"],a:1,
n:"Los GC <b>aumentan</b> la excreción renal de calcio (y de fósforo y nitrógeno) y reducen su absorción intestinal; la bajada de calcio estimula la paratiroides. Además aumentan la glucemia y el glucógeno hepático y son catabólicos proteicos."},
{t:2,q:"Los setrones. Señala la proposición INCORRECTA:",o:["Son eficaces en los vómitos por cinetosis","Son útiles en los vómitos de origen central","Pueden administrarse por vía intravenosa","Pueden producir hipotensión y bradicardia"],a:0,
n:"Los setrones (antagonistas 5-HT3) <b>no funcionan en el vómito por cinetosis</b>, en el que intervienen vías vestibulares (H1 y muscarínicas); ahí van mejor el maropitant o los antiH1. Sí son útiles en vómitos de origen central (zona gatillo), se pueden dar por vía IV y pueden causar hipotensión y bradicardia."},
{t:3,q:"Reacciones adversas de los AINEs. Señala la proposición INCORRECTA:",o:["Pueden producir acidosis mixta, respiratoria y metabólica, especialmente el AAS","Pueden provocar hiperuricemia e hipertensión en tratamientos crónicos","Son ulcerógenos y dificultan la reepitelización de la mucosa","Por inhibición en el aparato yuxtaglomerular originan activación del sistema renina-angiotensina-aldosterona"],a:3,
n:"Al inhibir las prostaglandinas del aparato yuxtaglomerular, los AINEs <b>disminuyen</b> la renina y la aldosterona (no activan el sistema), lo que contribuye a la hiperpotasemia. Sí pueden producir acidosis mixta (sobre todo los salicilatos), hiperuricemia e hipertensión en tratamientos largos, y son ulcerógenos."},
{t:2,q:"Antihistamínicos H1 (2ª generación). Señala la INCORRECTA:",o:["Presentan vidas medias prolongadas que permiten su administración una vez al día","Su excreción es principalmente renal al ser menos liposolubles","Se unen poco a proteínas plasmáticas y son poco metabolizados","Tienen una acción más selectiva, con poco bloqueo de otros receptores autonómicos"],a:2,
n:"Los antiH1 de 2ª generación tienen una <b>alta unión a proteínas</b> y un <b>metabolismo hepático importante</b> (CYP3A4). El resto es cierto: vida media larga (una dosis al día), excreción sobre todo renal y acción más selectiva."},
{t:2,q:"Efectos farmacológicos de la serotonina. Señala la proposición CORRECTA:",o:["Vasodilatación arteriolar y venosa en cerebro y vísceras","Efecto cronotropo e inotropo negativo","Actividad antiagregante","Aumenta la agresividad"],a:2,d:true,
n:"Es la versión del examen de julio de 2021, y su clave marca la <b>actividad antiagregante</b>. Las demás son falsas: en cerebro y vísceras la serotonina produce <b>vasoconstricción</b>, es crono e inotropa <b>positiva</b> y <b>disminuye</b> la agresividad.<br>Ojo: en farmacología general la serotonina favorece la agregación plaquetaria (5-HT2A); si tu profesora la explica como antiagregante, quédate con su criterio."}
];
QUESTIONS.forEach((q,i)=>q.id=i);
